import { Agent, GameEngine } from "../game";
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";

export class TargetingSystem {
    /**
     * 計算有效射程（考慮高地加成）
     */
    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        const h1 = engine.map.getTerrainHeight(a.q, a.r);
        const h2 = engine.map.getTerrainHeight(targetQ, targetR);
        const deltaH = h1 - h2;
        const heightBonus = deltaH > 0 ? Math.floor(deltaH / BLOCK_HEIGHT * 0.5) : 0;
        return baseRange + heightBonus;
    }

    /**
     * RTS 等級目標選取評分
     * 考慮距離、殘血程度、以及最重要的「威脅度」（是否正在詠唱奧義）
     */
    public updateTarget(a: Agent, engine: GameEngine) {
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;

        let maxScore = -Infinity;
        let bestTarget: Agent | null = null;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const dist = Math.max(1, HexUtils.dist(a, o));

                // 1. 基礎距離權重 (反比平方，極度優先近處)
                const distScore = 50 / (dist * dist);

                // 2. 血量權重 (優先擊殺殘血)
                const hpScore = (1 - o.hp / o.maxHp) * 15;

                // 3. 威脅權重 (重點修復：優先沉默/打斷奧義)
                let threatScore = 0;
                if (o.castingSkillIdx !== -1) {
                    const castingSkill = o.skills[o.castingSkillIdx];
                    if (castingSkill?.tag === 'ULT') {
                        threatScore = 100; // 絕對優先級：正在放大的敵人
                    } else if (castingSkill?.tag === 'ACTIVE') {
                        threatScore = 30;  // 高優先級：正在放技能的敵人
                    }
                }

                // 總分計算
                const score = distScore + hpScore + threatScore;

                if (score > maxScore) {
                    maxScore = score;
                    bestTarget = o;
                }
            }
        }
        a.target = bestTarget;
    }

    public calculateOptimalTarget(source: Agent, skill: Skill, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        if (skill.type === 'AOE') {
            return this.findBestAOELocation(source, skill, engine);
        }
        if (!source.target) this.updateTarget(source, engine);
        return { targetAgent: source.target, targetHex: null };
    }

    public getImpactArea(source: Agent, targetHex: Hex, skill: Skill, engine: GameEngine): Hex[] {
        if (skill.type === 'AOE') {
            const radius = skill.aoeRadius || 1;
            return HexUtils.range(targetHex, radius).filter(h => engine.map.isValid(h.q, h.r));
        }
        return [targetHex];
    }

    private findBestAOELocation(source: Agent, skill: Skill, engine: GameEngine) {
        const range = skill.range;
        const radius = skill.aoeRadius || 1;
        const enemies = engine.agents.filter(e => e.team !== source.team && e.hp > 0 && !e.banished);

        if (enemies.length === 0) return { targetAgent: null, targetHex: null };

        let bestHex: Hex | null = null;
        let maxImpact = -1;

        const candidates = new Set<string>();
        enemies.forEach(e => {
            candidates.add(HexUtils.key(e));
            HexUtils.neighbors(e).forEach(n => candidates.add(HexUtils.key(n)));
        });

        candidates.forEach(key => {
            const [q, r] = key.split(',').map(Number);
            const targetHex = { q, r };
            if (!engine.map.isValid(q, r)) return;
            if (HexUtils.dist(source, targetHex) > this.getEffectiveRange(source, q, r, range, engine)) return;

            let impact = 0;
            enemies.forEach(e => {
                if (HexUtils.dist(targetHex, e) <= radius) {
                    // AOE 權重同樣計入正在詠唱的目標
                    const weight = (e.castingSkillIdx !== -1 && e.skills[e.castingSkillIdx]?.tag === 'ULT') ? 5.0 : 1.0;
                    impact += weight * (1.0 + (1 - e.hp/e.maxHp));
                }
            });

            if (impact > maxImpact) {
                maxImpact = impact;
                bestHex = targetHex;
            }
        });

        return { targetAgent: null, targetHex: bestHex };
    }
}

import { Agent, GameEngine } from "../game";
import { NodeState } from "../../types";
import { HexUtils } from "../utils";

export type BTConditionFn = (agent: Agent, engine: GameEngine, args?: any) => boolean;
export type BTActionFn = (agent: Agent, engine: GameEngine, args?: any) => NodeState;

export const BTConditions: Record<string, BTConditionFn> = {
    "IsDead": (a) => a.hp <= 0,
    "IsAlive": (a) => a.hp > 0,
    "IsStunned": (a) => a.stunTimer > 0,
    "IsBanished": (a) => a.banishTimer > 0,
    "IsSilenced": (a) => a.silenceTimer > 0,
    "HasTarget": (a, engine) => {
        // RTS 頻率：每 0.5 秒強制掃描一次威脅最高目標，或在沒有目標時掃描
        if (engine.battleTime % 0.5 < 0.02 || !a.target) {
            engine.updateTarget(a);
        }
        return a.target !== null;
    },
    "HpBelow": (a, _, args) => (a.hp / a.maxHp) < args.threshold,
    "MpAbove": (a, _, args) => a.mp >= args.amount,
    "SkillReady": (a, _, args) => {
        const idx = args.slot; 
        const s = a.skills[idx];
        if (!s) return false;
        // 數學容差 CD 檢查
        return a.curCDs[idx] <= 0.01 && a.mp >= s.cost && a.stunTimer <= 0 && !a.banished;
    },
    "FindOptimalTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        // 執行數學權重搜索
        const res = engine.calculateOptimalTarget(a, skill);
        if (res.targetAgent) {
            a.target = res.targetAgent;
            a.targetHex = null;
        } else if (res.targetHex) {
            a.target = null;
            a.targetHex = res.targetHex;
        }
        return (a.target !== null || a.targetHex !== null);
    },
    "IsTargetInRange": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;
        const targetPos = a.targetHex || (a.target ? {q: a.target.q, r: a.target.r} : null);
        if (!targetPos) return false;

        // 使用動態射程判定 (考慮地勢)
        const effRange = engine.getEffectiveRange(a, targetPos.q, targetPos.r, skill.range);
        return HexUtils.dist(a, targetPos) <= effRange;
    }
};

export const BTActions: Record<string, BTActionFn> = {
    "Wait": (a, engine, args) => {
        a.btStatus = args.status || "等待";
        return NodeState.RUNNING;
    },
    "Idle": (a) => {
        a.btStatus = "待機中";
        return NodeState.SUCCESS;
    },
    "CastSkill": (a, engine, args) => {
        const idx = args.slot;
        return engine.initiateCast(a, idx);
    },
    "MoveToOptimal": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        const targetPos = a.targetHex || (a.target ? {q: a.target.q, r: a.target.r} : null);
        if (!skill || !targetPos) return NodeState.FAILURE;

        const speedMult = (skill.tag === 'ULT') ? 1.3 : 1.0;
        return engine.moveAgentToHex(a, targetPos, skill.range, speedMult);
    },
    "ChaseTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill || !a.target) return NodeState.FAILURE;

        // RTS 優化：攔截預判
        // 只有當目標距離我「預定路徑終點」超過容差時才重新計算 A*
        const currentGoal = a.path.length > 0 ? a.path[a.path.length - 1] : null;
        const tolerance = (a.target.isMoving) ? 1.5 : 0.5;
        const needsNewPath = !currentGoal || HexUtils.dist(currentGoal, a.target) > tolerance;

        if (needsNewPath) {
            const speedMult = (skill.tag === 'ULT') ? 1.4 : 1.1;
            a.btStatus = `截擊 ${a.target.id}`;
            return engine.moveAgentToHex(a, {q: a.target.q, r: a.target.r}, skill.range, speedMult);
        }

        return NodeState.RUNNING;
    }
};

import { Agent, GameEngine } from "../game";
import { Hex, MovementType } from "../../types";
import { HexUtils, NEIGHBOR_HASH_OFFSETS } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";
import { OBSTACLE_DB } from "../../data/obstacles";
import { TargetingSystem } from "./TargetingSystem";

interface PQNode {
    hash: number;
    priority: number;
}

export class Pathfinder {
    private _gScore = new Map<number, number>();
    private _cameFrom = new Map<number, number>();
    private _pq: PQNode[] = [];

    public findPath(startAgent: Agent, endQ: number, endR: number, range: number, ignoreUnits: boolean, engine: GameEngine, targeting: TargetingSystem): Hex[] {
        const startH = HexUtils.hash(startAgent.q, startAgent.r);
        const goalHex = { q: endQ, r: endR };

        // 射程檢查：若已在動態射程內，則無需移動
        const effRange = targeting.getEffectiveRange(startAgent, endQ, endR, range, engine);
        if (HexUtils.dist(startAgent, goalHex) <= effRange) return [];

        this._gScore.clear();
        this._cameFrom.clear();
        this._pq = [];

        this._gScore.set(startH, 0);
        this.pqPush(startH, 0);

        let iterations = 0;
        let bestH = -1;
        const MAX_ITER = 600; 

        while (this._pq.length > 0 && iterations < MAX_ITER) {
            iterations++;
            const current = this.pqPop()!;
            const currentHex = HexUtils.unhash(current.hash);

            // 成功判定：進入有效射程
            if (HexUtils.dist(currentHex, goalHex) <= targeting.getEffectiveRange(currentHex, endQ, endR, range, engine)) {
                bestH = current.hash;
                break;
            }

            for (let i = 0; i < 6; i++) {
                const neighborH = current.hash + NEIGHBOR_HASH_OFFSETS[i];
                if (!engine.map.isValidHash(neighborH)) continue;

                // 物理碰撞判定
                if (engine.map.hasObstacleHash(neighborH)) {
                    const type = engine.map.obstacles.get(HexUtils.key(HexUtils.unhash(neighborH)));
                    const def = OBSTACLE_DB[type || 'WALL'];
                    if (startAgent.movementType === MovementType.FLYING ? def?.blocksFlying : def?.blocksMovement) continue;
                }

                if (!ignoreUnits) {
                    const occ = engine.agentMap.get(neighborH);
                    if (occ && occ.hp > 0 && occ !== startAgent) continue;
                }

                // 數學地勢成本計算
                const nHex = HexUtils.unhash(neighborH);
                let moveCost = 1.0;
                if (startAgent.movementType !== MovementType.FLYING) {
                    const h1 = engine.map.getTerrainHeight(currentHex.q, currentHex.r);
                    const h2 = engine.map.getTerrainHeight(nHex.q, nHex.r);
                    const diff = Math.abs(h1 - h2);
                    if (diff > Math.max(1, startAgent.jump) * BLOCK_HEIGHT) continue; 
                    moveCost += diff / BLOCK_HEIGHT * 0.4; 
                }

                const tentativeG = (this._gScore.get(current.hash) || 0) + moveCost;

                if (!this._gScore.has(neighborH) || tentativeG < this._gScore.get(neighborH)!) {
                    this._cameFrom.set(neighborH, current.hash);
                    this._gScore.set(neighborH, tentativeG);

                    // 核心數學：六邊形 Cube 曼哈頓距離啟發函數
                    const hCost = HexUtils.dist(nHex, goalHex);
                    this.pqPush(neighborH, tentativeG + hCost);
                }
            }
        }

        return bestH !== -1 ? this.reconstructPath(bestH, startH) : [];
    }

    private pqPush(hash: number, priority: number) {
        this._pq.push({ hash, priority });
        // 生產環境應使用 Binary Heap，此處使用排序模擬
        this._pq.sort((a, b) => a.priority - b.priority); 
    }

    private pqPop() { return this._pq.shift(); }

    private reconstructPath(current: number, startH: number): Hex[] {
        const path: Hex[] = [];
        let curr = current;
        while (curr !== startH && path.length < 100) {
            path.push(HexUtils.unhash(curr));
            curr = this._cameFrom.get(curr) || -1;
        }
        return path.reverse();
    }
}

import { Agent } from "../game";
import { Particle } from "../systems/vfx/state";
import { Projectile, Point, GroundHazard } from "../../types";

export enum RenderOpType {
    TERRAIN,
    OBSTACLE,
    UNIT,
    VFX,
    PROJECTILE,
    DECAL
}

export class RenderOp {
    type: RenderOpType = RenderOpType.TERRAIN;
    sortKey: number = 0;
    y: number = 0; 
    z: number = 0; 
    tx: number = 0; ty: number = 0; th: number = 0; 
    tsize: number = 0; ttheme: any = null;
    tq: number = 0; tr: number = 0;
    ttype: string = ''; tdetail: string = '';
    oStatus: string | undefined;
    oDanger: any;
    oHazard: GroundHazard | undefined; 
    oLightCol: string | null = null;
    oLightInt: number = 0;
    oRange: boolean = false;
    oRangeCol: string = '';
    oHover: boolean = false;
    oHasUnit: boolean = false;
    agent: Agent | null = null;
    uSelected: boolean = false;
    uSilhouette: boolean = false;
    particle: Particle | null = null;
    vProgress: number = 0;
    vChaos: boolean = false;
    pVisX: number = 0; pVisY: number = 0; pVisShadowY: number = 0;
    pSkillVis: string = ''; pColor: string = '';
    pIsUlt: boolean = false; pAngle: number = 0; pSpin: number = 0;
    pTrail: Point[] = []; 
    proj: Projectile | null = null;
    dColor: string = ''; dScale: number = 1; dLife: number = 0;
    time: number = 0;

    public clear() {
        this.type = RenderOpType.TERRAIN;
        this.sortKey = 0;
        this.y = 0; this.z = 0;
        this.tx = 0; this.ty = 0; this.th = 0;
        this.agent = null;
        this.particle = null;
        this.proj = null;
        this.pIsUlt = false; 
        this.oRange = false;
        this.oHover = false;
        this.oStatus = undefined;
        this.oHazard = undefined;
        this.oDanger = undefined;
        this.uSelected = false;
        this.uSilhouette = false;
        this.vChaos = false;
        this.ttheme = null;
        this.pTrail = [];
    }
}

export class RenderList {
    public ops: RenderOp[] = [];
    public count: number = 0;
    private sortView: RenderOp[] = [];
    private capacity: number = 8000;

    constructor() {
        for(let i=0; i<this.capacity; i++) {
            const op = new RenderOp();
            this.ops.push(op);
            this.sortView.push(op); 
        }
    }

    public reset() {
        this.count = 0;
    }

    public next(): RenderOp {
        if (this.count >= this.ops.length) {
            for(let i=0; i<1000; i++) {
                const op = new RenderOp();
                this.ops.push(op);
                this.sortView.push(op);
            }
        }
        const op = this.ops[this.count++];
        op.clear(); 
        return op;
    }

    public sort() {
        if (this.count <= 1) return;
        for (let i = 0; i < this.count; i++) {
            const op = this.ops[i];

            // 核心數學排序公式：分層架構
            // Band 30M: 浮空 UI/頂層特效
            // Band 20M: 奧義與大型演出 (Cinematic Layer)
            // Band 0: 一般場景物件 (Sorted by Y)
            // Band -10M: 地表裝飾/影子

            let layerScore = 0;
            const isCinematic = (op.type === RenderOpType.VFX || op.type === RenderOpType.PROJECTILE) && op.pIsUlt;

            if (op.z > 500) {
                layerScore = 30000000; 
            } else if (isCinematic) {
                layerScore = 25000000; // 提升奧義層優先級
            } else if (op.z < 0) {
                layerScore = -10000000;
            }

            // 使用整數座標進行穩定排序，防止浮點數抖動
            const yScore = Math.floor(op.y) * 1000;
            const zScore = Math.floor(op.z);

            op.sortKey = layerScore + yScore + zScore;
            this.sortView[i] = op;
        }

        const activeSegment = this.sortView.slice(0, this.count);
        activeSegment.sort((a, b) => a.sortKey - b.sortKey);

        for (let i = 0; i < this.count; i++) {
            this.ops[i] = activeSegment[i];
        }
    }
}

import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { Point3D } from "./EventVFXMapper";
import { VFXSequence, VFXAction } from "../../../types/VFXSchema";
import { VisualMath } from "../../math/VisualMath";

/**
 * ECS VFX Sequence Runner v10.5
 * 強化奧義演出之座標精確度與物理模擬
 */
export class SequenceSystem {

    public static run(
        sequence: VFXSequence,
        target: Point3D,
        engine: GameEngine,
        vfx: VFXSystem,
        sourceId?: string
    ) {
        let sourcePos: Point3D | undefined;

        if (sourceId) {
            const agent = engine.agents.find(a => a.id === sourceId);
            if (agent) sourcePos = VisualMath.getUnitAnchor(agent, engine);
        }

        sequence.actions.forEach(action => {
            const execute = () => {
                this.dispatch(action, target, sourcePos, vfx, engine);
            };

            if (action.delay && action.delay > 0) {
                setTimeout(execute, action.delay * 1000);
            } else {
                execute();
            }
        });
    }

    private static dispatch(action: VFXAction, target: Point3D, source: Point3D | undefined, vfx: VFXSystem, engine: GameEngine) {
        const effectId = action.id || 'FX_HIT_GENERIC';

        // 數學修正：獲取精確地面高度，並套用微小 Bias 解決穿插
        const groundZ = target.z - 2; 

        switch (action.type) {
            case 'PARTICLE':
                // 奧義粒子強制帶入 pIsUlt 標記（透過 ID 判定或 action 配置）
                vfx.playEffect(effectId, target.x, target.y, target.z, action.color, groundZ);
                break;

            case 'BEAM':
                if (source) {
                    vfx.playBeam(action.style || 'GENERIC_BEAM', source, target, action.color, action.duration || 0.4);
                }
                break;

            case 'SHAKE':
                if (engine.renderer) engine.renderer.camera.addTrauma(action.shakeIntensity || 0.3);
                break;

            case 'GRID_PULSE':
                // 強制網格中心對齊
                vfx.playEffect(
                    action.color?.includes('#3b') ? 'FX_GRID_IMPACT_BLUE' : 'FX_GRID_IMPACT_RED', 
                    target.x, target.y, groundZ + 4, 
                    action.color, groundZ
                );
                break;

            case 'HEAVEN_FALL':
                const h = action.height || 1200;
                const p = vfx.state.getParticle();
                p.x = target.x; p.y = target.y; p.z = target.z + h;
                p.vz = -3500; // 奧義掉落物應有更高初速
                p.life = (h / 3500) + 0.1; 
                p.maxLife = p.life;
                p.color = action.color || '#fff';
                p.size = (action.scale || 1.8) * 80;
                p.type = action.style === 'METEOR' ? 'ROCK' : 'GIANT_HEX';
                p.locked = false;
                // 標記為奧義組件，影響渲染排序
                (p as any).pIsUlt = true; 
                vfx.state.particles.push(p);
                break;
        }
    }
}

import { ZoneRenderer } from "./ZoneRenderer";
import { HazardPainter } from "./painters/HazardPainter"; 
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard, HexLayout } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { ActiveZone } from "../../systems/ZoneSystem";
import { HexUtils } from "../../utils";

// 唯一數學常數：抬升量 (像素)
// 確保渲染順序： 地形 < 區域標記 < 傷害陷阱 < 單位
const OVERLAY_LIFT = -3;
const HAZARD_LIFT = -8; 

export const GridOverlays = {
    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, 
        size: number,
        specialStatus: string | undefined, 
        zoneInfo: ActiveZone | undefined,    
        lightColor: string | null,
        lightIntensity: number,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined,
        layout: HexLayout
    ) {
        // 1. 繪製環境陷阱 (高優先級地表)
        if (hazard) {
            HazardPainter.draw(ctx, x, y + HAZARD_LIFT, hazard, globalTime);
        }

        const drawY = y + OVERLAY_LIFT;

        // 2. 狀態地效 (如：凝滯區域)
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                ctx.translate(x, drawY);
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.4;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.fill();
                ctx.restore();
            }
        }

        // 3. 戰術區域 (奧義預警/AOE 範圍)
        if (zoneInfo) {
            const dist = HexUtils.dist({q, r}, {q: zoneInfo.q, r: zoneInfo.r});
            ZoneRenderer.drawTileZoneEffect(
                ctx, x, drawY - 1, size, // 稍微再抬升 1px 避免與 Hazard 重疊
                dist,
                zoneInfo.radius,
                zoneInfo.color,
                zoneInfo.progress,
                zoneInfo.isEnemy,
                layout
            );
        }

        // 4. 點光源投影
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.translate(x, drawY);
            ctx.globalCompositeOperation = 'screen'; 
            ctx.fillStyle = lightColor;
            ctx.globalAlpha = Math.min(0.5, lightIntensity * 0.4);
            HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
            ctx.fill();
            ctx.restore();
        }

        // 5. 交互高亮 (Range/Hover)
        if (isRange || isHover || hasUnit) {
            ctx.save();
            ctx.translate(x, drawY + 1); // 交互層最接近地形
            ctx.globalCompositeOperation = 'screen';
            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.12;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.95, true, layout);
                ctx.fill();
                ctx.strokeStyle = rangeColor;
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
                ctx.stroke();
            }
            if (isHover) { 
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.8;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.stroke();
            }
            ctx.restore();
        }
    }
};

import { GameEngine } from "../../game";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";
import { Camera } from "../../systems/CameraSystem";
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";

const GROUND_PROJECTION_TYPES = new Set([
    'GIANT_HEX', 'MAGIC_CIRCLE', 'RING', 'SHOCKWAVE', 
    'BLAST', 'HEX_GLOW', 'GRID_FIELD', 'CRACKS', 'DOMAIN'
]);

export class VFXRenderer {
    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        viewport?: { width: number, height: number, camera: Camera } 
    ) {
        let cullMinX = -Infinity, cullMaxX = Infinity, cullMinY = -Infinity, cullMaxY = Infinity;
        if (viewport) {
            const { width, height, camera } = viewport;
            const pad = 1200; 
            const viewW = width / camera.zoom;
            const viewH = height / camera.zoom;
            cullMinX = camera.x - (viewW / 2) - pad;
            cullMaxX = camera.x + (viewW / 2) + pad;
            cullMinY = camera.y - (viewH / 2) - pad;
            cullMaxY = camera.y + (viewH / 2) + pad;
        }

        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (p.x < cullMinX || p.x > cullMaxX || p.y < cullMinY || p.y > cullMaxY) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 1500) return;

            const op = renderList.next();
            op.type = RenderOpType.VFX;

            const isGroundLocked = GROUND_PROJECTION_TYPES.has(p.type);
            const isUlt = (p as any).pIsUlt || p.type === 'GIANT_HEX' || p.type === 'MAGIC_CIRCLE';

            op.y = p.y + offset + (isGroundLocked ? 2 : 0); 
            op.z = isGroundLocked ? (p.z + 5) : p.z; 
            op.pIsUlt = isUlt; // 核心：傳遞奧義標記至排序器

            op.particle = p;
            op.vProgress = 1 - (p.life / p.maxLife);
            op.vChaos = isChaosStyle(p.color);
            op.tx = p.x;
            op.ty = p.y + offset - p.z; 
            op.th = p.z; 
        });

        this.submitDecalLayer(renderList, vfx, mapConfig, transitionT, transitionPhase, cullMinX, cullMaxX, cullMinY, cullMaxY);
        ProjectileRenderer.submit(renderList, engine, transitionT, transitionPhase);
    }

    private submitDecalLayer(renderList: RenderList, vfx: VFXSystem, mapConfig: MapConfig, t: number, phase: any, minX: number, maxX: number, minY: number, maxY: number) {
        vfx.state.decals.forEach(d => {
            if (d.x < minX || d.x > maxX || d.y < minY || d.y > maxY) return;
            const offset = getTransitionOffset(d.x, d.y, mapConfig, t, phase);
            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = d.y + offset + 1; 
            op.z = 2; 
            op.tx = d.x; op.ty = d.y + offset; 
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });
    }
}

import { Agent } from "../game";
