}

export class RenderOp {
    type: RenderOpType = RenderOpType.TERRAIN;
    sortKey: number = 0;
    y: number = 0; 
    z: number = 0; 
    tx: number = 0; ty: number = 0; th: number = 0; 
    tsize: number = 0; ttheme: any = null;
    tq: number = 0; tr: number = 0;
    ttype: string = ''; tdetail: string = '';
    oStatus: string | undefined;
    oDanger: any;
    oHazard: GroundHazard | undefined; // 保留供系統引用
    oLightCol: string | null = null;
    oLightInt: number = 0;
    oRange: boolean = false;
    oRangeCol: string = '';
    oHover: boolean = false;
    oHasUnit: boolean = false;
    agent: Agent | null = null;
    uSelected: boolean = false;
    uSilhouette: boolean = false;
    particle: Particle | null = null;
    vProgress: number = 0;
    vChaos: boolean = false;
    pVisX: number = 0; pVisY: number = 0; pVisShadowY: number = 0;
    pSkillVis: string = ''; pColor: string = '';
    pIsUlt: boolean = false; pAngle: number = 0; pSpin: number = 0;
    pTrail: Point[] = []; 
    proj: Projectile | null = null;
    dColor: string = ''; dScale: number = 1; dLife: number = 0;
    time: number = 0;

    public clear() {
        this.type = RenderOpType.TERRAIN;
        this.sortKey = 0;
        this.y = 0; this.z = 0;
        this.tx = 0; this.ty = 0; this.th = 0;
        this.agent = null;
        this.particle = null;
        this.proj = null;
        this.pIsUlt = false; 
        this.oRange = false;
        this.oHover = false;
        this.oStatus = undefined;
        this.oHazard = undefined;
        this.oDanger = undefined;
        this.uSelected = false;
        this.uSilhouette = false;
        this.vChaos = false;
        this.ttheme = null;
        this.pTrail = [];
    }
}

export class RenderList {
    public ops: RenderOp[] = [];
    public count: number = 0;
    private sortView: RenderOp[] = [];
    private capacity: number = 8000;

    constructor() {
        for(let i=0; i<this.capacity; i++) {
            const op = new RenderOp();
            this.ops.push(op);
            this.sortView.push(op); 
        }
    }

    public reset() {
        this.count = 0;
    }

    public next(): RenderOp {
        if (this.count >= this.ops.length) {
            for(let i=0; i<1000; i++) {
                const op = new RenderOp();
                this.ops.push(op);
                this.sortView.push(op);
            }
        }
        const op = this.ops[this.count++];
        op.clear(); 
        return op;
    }

    public sort() {
        if (this.count <= 1) return;
        for (let i = 0; i < this.count; i++) {
            const op = this.ops[i];

            // --- 唯一數學排序體系 ---
            // 層級分配：
            // Band 30M: 浮空特效/UI
            // Band 25M: 奧義 Cinematic
            // Band 15M: 一般投射物 (Height-dependent)
            // Band 10M: 單位本體 (Sorted by Y)
            // Band 05M: 地面效果 (Hazards) -> 新增
            // Band 0: 地形表層

            let layerScore = 0;
            const isCinematic = (op.type === RenderOpType.VFX || op.type === RenderOpType.PROJECTILE) && op.pIsUlt;

            if (op.z > 500) {
                layerScore = 30000000; 
            } else if (isCinematic) {
                layerScore = 25000000;
            } else if (op.type === RenderOpType.UNIT) {
                layerScore = 10000000;
            } else if (op.type === RenderOpType.HAZARD) {
                layerScore = 5000000; // 核心：Hazards 永遠高於地形
            } else if (op.z < 0) {
                layerScore = -10000000;
            }

            const yScore = Math.floor(op.y) * 1000;
            const zScore = Math.floor(op.z);

            op.sortKey = layerScore + yScore + zScore;
            this.sortView[i] = op;
        }

        const activeSegment = this.sortView.slice(0, this.count);
        activeSegment.sort((a, b) => a.sortKey - b.sortKey);

        for (let i = 0; i < this.count; i++) {
            this.ops[i] = activeSegment[i];
        }
    }
}

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { SpriteManager } from "../../sprites";

const OBSTACLE_Z_INDEX = 10;
const PROJ_LIGHT_RADIUS_SQ = 1600;

/**
 * 網格渲染提交策略 - v11.0 (高階美術校正版)
 */
export class GridRenderStrategy {

    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];
        const layout = engine.mapConfig.layout;

        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            const visualBaseY = py + offset;
            const visualSurfaceY = visualBaseY - h;

            if (Math.abs(offset) > 800) continue;

            // 1. 提交障礙物
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = py; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                op.ty = visualSurfaceY; 
                op.ttype = obstacleType;
            }

            // 2. 提交地面效果 (Hazards) -> 從 Terrain 解耦，建立獨立 Op
            const hazard = engine.map.getHazardAt(q, r, engine);
            if (hazard) {
                const hOp = renderList.next();
                hOp.type = RenderOpType.HAZARD;
                hOp.y = py; 
                hOp.z = 5; // 低於單位，高於地板
                hOp.tx = px; 
                hOp.ty = visualSurfaceY; 
                hOp.oHazard = hazard;
                hOp.time = globalTime;
            }

            // 3. 提交地形與基礎 Overlays
            const zoneInfo = engine.zones.getZoneAt(q, r);
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexUtils.dist({q, r}, {q: highlightAgent.q, r: highlightAgent.r});
                if (dist <= hoveredSkill.range + bonus) { isRange = true; rangeColor = hoveredSkill.color; }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);

            // 投射物光照計算
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = py; 
            op.z = 0; 
            op.tx = px; 
            op.ty = visualBaseY; 
            op.th = h;
            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oLightCol = lightColor; op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { ZoneRenderer } from "./ZoneRenderer";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard, HexLayout } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { ActiveZone } from "../../systems/ZoneSystem";
import { HexUtils } from "../../utils";

const OVERLAY_LIFT = -3;

export const GridOverlays = {
    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, 
        size: number,
        specialStatus: string | undefined, 
        zoneInfo: ActiveZone | undefined,    
        lightColor: string | null,
        lightIntensity: number,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined, // 已棄用繪製
        layout: HexLayout
    ) {
        const drawY = y + OVERLAY_LIFT;

        // 1. 狀態地效
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                ctx.translate(x, drawY);
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.4;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.fill();
                ctx.restore();
            }
        }

        // 2. 戰術區域 (奧義預警/AOE 範圍)
        if (zoneInfo) {
            const dist = HexUtils.dist({q, r}, {q: zoneInfo.q, r: zoneInfo.r});
            ZoneRenderer.drawTileZoneEffect(
                ctx, x, drawY - 1, size,
                dist,
                zoneInfo.radius,
                zoneInfo.color,
                zoneInfo.progress,
                zoneInfo.isEnemy,
                layout
            );
        }

        // 3. 點光源投影
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.translate(x, drawY);
            ctx.globalCompositeOperation = 'screen'; 
            ctx.fillStyle = lightColor;
            ctx.globalAlpha = Math.min(0.5, lightIntensity * 0.4);
            HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
            ctx.fill();
            ctx.restore();
        }

        // 4. 交互高亮
        if (isRange || isHover || hasUnit) {
            ctx.save();
            ctx.translate(x, drawY + 1); 
            ctx.globalCompositeOperation = 'screen';
            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.12;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.95, true, layout);
                ctx.fill();
                ctx.strokeStyle = rangeColor;
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
                ctx.stroke();
            }
            if (isHover) { 
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.8;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.stroke();
            }
            ctx.restore();
        }
    }
};

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { HazardPainter } from "./grid/painters/HazardPainter"; // 引用
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";

export class RenderPipeline {
    private renderer: GameRenderer;
    private backgroundRenderer = new BackgroundRenderer();
    private tacticalRenderer = new TacticalRenderer();
    private hudRenderer = new HUDRenderer();
    private postProcessor = new PostProcessor();
    private renderList = new RenderList();
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';
    constructor(renderer: GameRenderer) { this.renderer = renderer; }
    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }
    public update(dt: number, engine: GameEngine) { this.tacticalRenderer.update(dt, engine); }
    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, globalTime: number): void {
        const physicalWidth = ctx.canvas.width, physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;
        const dpr = window.devicePixelRatio || 1, logicalWidth = physicalWidth / dpr, logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene, layout = engine.mapConfig.layout;
        ctx.resetTransform(); ctx.clearRect(0, 0, physicalWidth, physicalHeight); ctx.scale(dpr, dpr);
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);
        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);
        this.renderer.grid.submitRenderables(this.renderList, engine, hoveredHex, hoveredSkill, highlight, engine.projectiles, this.transitionT, this.transitionPhase, globalTime);
        this.renderer.vfxRenderer.submitRenderables(this.renderList, engine, this.renderer.vfx, terrainHeightFunc, engine.mapConfig, this.transitionT, this.transitionPhase, { width: logicalWidth, height: logicalHeight, camera });
        this.renderer.unit.submitRenderables(this.renderList, engine.agents, terrainHeightFunc, globalTime, highlight, engine.mapConfig);
        this.renderList.sort();
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i], snapX = Math.round(op.tx), snapY = Math.round(op.ty);
            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                    GridOverlays.drawOverlays(ctx, snapX, snapY - op.th, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, undefined, layout);
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);
                    break;
                case RenderOpType.HAZARD: // 新增：處理地面持續效果
                    if (op.oHazard) HazardPainter.draw(ctx, snapX, snapY, op.oHazard, op.time);
                    break;
                case RenderOpType.OBSTACLE:
                    ctx.drawImage(SpriteManager.getObstacleSprite(op.ttype, layout), snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette);
                    break;
                case RenderOpType.DECAL:
                    ctx.save(); ctx.translate(snapX, snapY); ctx.scale(op.dScale, op.dScale); ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(AssetManager.getBlastZone(op.dColor), -64, -32, 128, 64); ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) { ctx.save(); ctx.translate(snapX, snapY); ParticleRenderer.drawSingleParticle(ctx, op.particle, 0, 0, op.vProgress, op.vChaos, layout); ctx.restore(); }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }
        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) occludedAgents.forEach(agent => this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig));
        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        ctx.restore(); 
        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 
        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);
        let blurAmount = engine.victory.isFinishing ? 1.0 - (engine.victory.victoryTimer / VICTORY_PHASE_DURATION) : (engine.victory.winningTeam !== null ? 1.0 : 0);
        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;
        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}

import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

// 唯一數學常數：地面效果提升高度，杜絕穿插
const HAZARD_PLANE_LIFT = -3; 
const FOG_PLANE_LIFT = -15;

export const HazardPainter = {
    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];

        let fade = 1.0;
        if (hazard.duration < 0.8) fade = hazard.duration / 0.8;

        ctx.save();
        ctx.globalAlpha = fade;

        if (def.type === 'FOG') {
            const texture = VFXFactory.getTexture('SMOKE', def.primaryColor);
            const size = HEX_SIZE * 1.5;
            const speed = globalTime * def.speed;

            ctx.save();
            ctx.translate(x, y + FOG_PLANE_LIFT); // 高度偏置
            ctx.scale(1, ISO_SCALE_Y);

            ctx.globalCompositeOperation = (hazard.type === 'POISON') ? 'screen' : 'lighter';

            // 多層旋轉噪波模擬煙霧流動
            ctx.save();
            ctx.rotate(speed * 0.12);
            ctx.globalAlpha = def.intensity * 0.8;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            ctx.save();
            ctx.rotate(-speed * 0.08 + 1);
            ctx.scale(0.85, 0.85);
            ctx.globalAlpha = def.intensity * 0.5;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            ctx.restore();
        }
        else if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            // 諧波震盪：使邊緣產生律動感
            const intensity = def.intensity * (0.85 + Math.sin(speed * 0.8) * 0.15);

            ctx.save();
            ctx.translate(0, HAZARD_PLANE_LIFT); // 物理微抬升
            SurfacePainter.drawLiquid(ctx, x, y, def.primaryColor, speed, intensity);
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, y, def.secondaryColor, intensity * 0.8);
            ctx.restore();
        }
        else if (def.type === 'CRYSTAL') {
            // 晶體類具備體積感
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, y + HAZARD_PLANE_LIFT, HEX_SIZE * 0.8, 8, def.primaryColor, 0.7);

            ctx.save();
            ctx.translate(x, y + HAZARD_PLANE_LIFT - 5); 
            ctx.scale(1, ISO_SCALE_Y);
            const texture = VFXFactory.getTexture('ROCK', def.secondaryColor);
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.6;
            ctx.drawImage(texture, -15, -15, 30, 30);
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            ctx.save();
            ctx.translate(x, y + HAZARD_PLANE_LIFT);
            ctx.scale(1, ISO_SCALE_Y);

            const r = HEX_SIZE * 0.8;
            // 事件視界漸變
            const grad = ctx.createRadialGradient(0, 0, r * 0.1, 0, 0, r);
            grad.addColorStop(0, '#000');
            grad.addColorStop(0.5, 'rgba(0,0,0,0.8)');
            grad.addColorStop(0.8, def.secondaryColor);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.8 * def.intensity;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

            // 吸入感動態環
            ctx.strokeStyle = def.secondaryColor;
            ctx.lineWidth = 2;
            const cycle = (globalTime * 2) % 1;
            ctx.globalAlpha = 0.4 * (1 - cycle);
            ctx.beginPath(); ctx.arc(0, 0, r * (1 - cycle), 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }

        ctx.restore();
    }
};

import { Agent } from "../../game";
import { ShieldPainter } from "./painters/ShieldPainter";
import { OverheadPainter } from "./painters/OverheadPainter";
import { GroundEffectPainter } from "./painters/GroundEffectPainter";
import { StateModelPainter } from "./painters/StateModelPainter";
import { VisualMath } from "../../math/VisualMath";

/**
 * ECS Status Orchestrator v11.5
 * 負責所有單位狀態特效的座標解算與渲染分發
 */
export class StatusOrchestrator {

    public draw(
        ctx: CanvasRenderingContext2D, 
        agents: Agent[], 
        globalTime: number,
        getTerrainHeight: (q: number, r: number) => number
    ) {
        for (const agent of agents) {
            // 跳過已徹底消失的單位
            if (agent.hp <= 0 && agent.fullyDead) continue;

            // 基礎幾何解算 (SSOT)
            const px = agent.px + agent.physics.x;
            const py = agent.py + agent.physics.y;
            const pz = agent.physics.z;

            const terrainH = getTerrainHeight(agent.q, agent.r);
            const visualFloorY = py - terrainH; 

            // 核心數學：解算身體中心點（用於護盾與包裹類特效）
            const bodyCenterY = VisualMath.getVisualBodyCenterY(visualFloorY, pz);

            // 1. 放逐/凝滯 (最高級狀態覆蓋)
            if (agent.banished) {
                StateModelPainter.drawBanishment(ctx, agent, px, bodyCenterY, globalTime);
                continue; // 處於放逐狀態時通常不顯示其他 UI 特效
            }

            // 2. 地面鎖定效果 (Root/Burning)
            // 強制腳底偏置：-5px 確保在地板之上且在 Token 之下
            GroundEffectPainter.draw(ctx, agent, px, visualFloorY - pz, globalTime);

            // 3. 護盾 (Volumetric Shell)
            // 護盾必須跟隨 bodyCenterY
            ShieldPainter.draw(ctx, agent, px, bodyCenterY, globalTime);

            // 4. 頭頂狀態圖標 (Floating HUD)
            // 圖標高度 = 中心點 - 模型高度偏移
            OverheadPainter.draw(ctx, agent, px, bodyCenterY, globalTime);
        }
    }
}

import { Agent } from "../../../../game";
import { ISO_SCALE_Y } from "../../../../../constants";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

// 數學規範：CC 地面層偏置量
const CC_GROUND_BIAS = -5;

export const GroundEffectPainter = {
    /**
     * 繪製單位腳下的持續性 CC 特效
     * @param y 單位目前的視覺腳底高度 (含物理 Z)
     */
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number) {
        // 1. 禁錮效果 (Root / Vines)
        if (agent.rootTimer > 0) {
            const color = '#fbbf24'; 
            ctx.save();
            ctx.translate(x, y + CC_GROUND_BIAS);

            // 幾何脈衝函數
            const pulse = 0.8 + Math.sin(t * 12) * 0.15;
            const r = 24 * pulse;

            // A. 底層能量環 (Vector Hex)
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.6;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            HexGeometry.traceHex(ctx, 0, 0, r, true);
            ctx.stroke();

            // B. 3D 突刺 (幾何模擬)
            ctx.fillStyle = color;
            ctx.globalCompositeOperation = 'source-over';
            const count = 3;
            for(let i=0; i<count; i++) {
                const angle = i * (Math.PI*2/count) + t * 2;
                const sx = Math.cos(angle) * (r * 0.7);
                const sy = Math.sin(angle) * (r * 0.7) * ISO_SCALE_Y;

                ctx.beginPath();
                ctx.moveTo(sx, sy);
                ctx.lineTo(sx, sy - 20); // 垂直向上的幾何刺
                ctx.lineTo(sx + 5, sy + 2);
                ctx.fill();
            }
            ctx.restore();
        }

        // 2. 灼燒/DoT 地標 (Burn Ground)
        if (agent.dotTimer > 0 && agent.dotDmg > 0) {
            ctx.save();
            ctx.translate(x, y + CC_GROUND_BIAS + 1); // 再低 1px
            ctx.globalCompositeOperation = 'lighter';

            const r = 18 + Math.sin(t * 15) * 2;
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
            grad.addColorStop(0, 'rgba(239, 68, 68, 0.4)');
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.scale(1, ISO_SCALE_Y);
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }
    }
};

import { Agent } from "../../../../game";
import { Team } from "../../../../../types";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const ShieldPainter = {
    /**
     * 繪製包裹單位的能量護盾
     * @param y 單位視覺中心 Y 軸
     */
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number) {
        if (agent.shield <= 0) return;

        const isBlue = agent.team === Team.BLUE;
        const color = isBlue ? '#60a5fa' : '#ef4444';

        // 護盾強度視覺映射
        const pct = Math.min(1, agent.shield / (agent.maxShield || 100));
        const pulse = 0.2 + (pct * 0.4) + Math.sin(t * 5) * 0.1;

        ctx.save();
        ctx.translate(x, y); 

        // 使用 3D 稜柱繪製體積感
        // 向上抬升一半高度以實現垂直居中
        const shieldH = 80;
        const shieldR = 38;

        ctx.globalCompositeOperation = 'screen';
        VolumePainter.draw3DPrism(ctx, 0, shieldH/2, shieldR, shieldH, color, pulse, 'SOLID');

        // 邊緣掃描線 (TA 效果)
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 1;
        ctx.globalAlpha = pulse * 0.5;
        const scanLineY = (t * 100) % shieldH - shieldH/2;
        ctx.beginPath();
        ctx.moveTo(-shieldR * 0.8, scanLineY);
        ctx.lineTo(shieldR * 0.8, scanLineY);
        ctx.stroke();

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { AssetManager } from "../../../assets";
import { STATUS_VISUALS } from "../../../../../data/vfx/status_visuals";
import { VISUAL_ANCHORS } from "../../../../../constants";

export const OverheadPainter = {
    /**
     * 繪製頭頂狀態圖標
     * @param y 單位視覺中心 Y 軸
     */
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number) {
        // 優先權檢查
        let type = '';
        if (agent.stunTimer > 0) type = 'STUN';
        else if (agent.fearTimer > 0) type = 'FEAR';
        else if (agent.tauntTimer > 0) type = 'TAUNT';
        else if (agent.silenceTimer > 0) type = 'SILENCE';
        else if (agent.blindTimer > 0) type = 'BLIND';

        if (!type) return;

        const icon = AssetManager.getStatusIcon(type);
        if (!icon) return;

        // 數學波形：平滑垂直震盪
        const bob = Math.sin(t * 8) * 4;

        // 錨點：從身體中心向上偏移固定量
        const anchorY = y - VISUAL_ANCHORS.HEAD_OFFSET_Y - 15 + bob; 

        ctx.save();
        ctx.translate(x, anchorY);

        const def = STATUS_VISUALS[type];
        const color = def?.primaryColor || '#fff';

        // 渲染發光層
        ctx.shadowColor = color;
        ctx.shadowBlur = 12;
        ctx.globalAlpha = 0.9;

        ctx.drawImage(icon, -20, -20, 40, 40);

        // 暈眩星光特效
        if (type === 'STUN') {
            ctx.rotate(t * 4);
            ctx.fillStyle = '#fff';
            for(let i=0; i<3; i++) {
                const a = i * (Math.PI*2/3);
                const starDist = 22;
                ctx.beginPath(); 
                ctx.arc(Math.cos(a)*starDist, Math.sin(a)*starDist, 2.5, 0, Math.PI*2); 
                ctx.fill();
            }
        }

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { AssetManager } from "../../../assets";

export const StateModelPainter = {
    /**
     * 繪製包裹單位的放逐/凝滯幾何體
     * @param centerY 單位視覺中心 Y 軸
     */
    drawBanishment(ctx: CanvasRenderingContext2D, agent: Agent, x: number, centerY: number, t: number) {
        if (!agent.banished) return;

        const isStasis = agent.visualStatus === 'STASIS';
        const color = isStasis ? '#facc15' : '#c084fc'; 
        const shadowColor = isStasis ? '#eab308' : '#7e22ce';

        ctx.save();
        ctx.translate(x, centerY);

        // 核心幾何參數
        const size = 50;
        const halfH = 70;
        const rot = t * 1.2;

        // 解算 4 個旋轉頂點 (ISO 平面)
        const pts = [];
        for(let i=0; i<4; i++) {
            const angle = rot + (i * Math.PI / 2);
            pts.push({
                x: Math.cos(angle) * size,
                y: Math.sin(angle) * size * 0.4 // ISO 透視壓縮
            });
        }

        // 幾何繪製函數
        const drawShard = (p1: any, p2: any, tipY: number, alpha: number) => {
            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.lineTo(0, tipY);
            ctx.closePath();

            ctx.fillStyle = color;
            ctx.globalAlpha = alpha;
            ctx.fill();

            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.5;
            ctx.stroke();
        };

        // 浮動動畫
        const bob = Math.sin(t * 3) * 6;
        ctx.translate(0, bob);

        // 繪製稜鏡面
        for(let i=0; i<4; i++) {
            const next = (i+1)%4;
            drawShard(pts[i], pts[next], -halfH, 0.3); // 上半部
            drawShard(pts[i], pts[next], halfH, 0.15); // 下半部
        }

        // 核心狀態圖標
        ctx.globalCompositeOperation = 'screen';
        const pulse = 0.8 + Math.sin(t * 6) * 0.2;
        ctx.globalAlpha = pulse;
        const icon = AssetManager.getStatusIcon(isStasis ? 'STASIS' : 'BANISH');
        if (icon) ctx.drawImage(icon, -24, -24, 48, 48);

        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { HEX_SIZE } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

// 唯一數學常數：詠唱法陣標準抬升量，徹底解決 Z-fighting
const AURA_FLOOR_LIFT = -1.5; 

export const UnitAuraPainter = {

    /**
     * 繪製標準技能詠唱特效 (Vector Geometry)
     */
    drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        ctx.save();
        ctx.translate(x, y + AURA_FLOOR_LIFT); 

        // 核心數學：法陣半徑隨律動震盪
        const baseSize = HEX_SIZE * 0.95;
        const pulse = Math.sin(t * 12) * 0.05;
        const currentSize = baseSize * (1.0 + pulse);

        ctx.strokeStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 12;

        // 1. 旋轉能量環 (外環：順時針)
        const rotA = t * 3;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.6;
        HexGeometry.traceRotatedHex(ctx, 0, 0, currentSize, rotA, true);
        ctx.stroke();

        // 2. 幾何核心 (內環：逆時針，高頻旋轉)
        const rotB = -t * 6;
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.4;
        HexGeometry.traceRotatedHex(ctx, 0, 0, currentSize * 0.7, rotB, true);
        ctx.stroke();

        // 3. 能量溢出點 (Procedural)
        this.drawRisingParticles(ctx, color, progress, t);

        ctx.restore();

        // 4. 若為 AOE，繪製精確的邊界指示器
        if (skill.type === 'AOE') {
            this.drawAoeExpansion(ctx, x, y, color, progress, skill.aoeRadius || 1);
        }
    },

    /**
     * 繪製奧義詠唱聖域 (Epic Geometry)
     */
    drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        ctx.save();
        ctx.translate(x, y + AURA_FLOOR_LIFT);

        // 奧義法陣規模較大
        const ultSize = HEX_SIZE * 2.5; 
        const rot = t * 1.5;

        ctx.shadowColor = color;
        ctx.shadowBlur = 20;
        ctx.strokeStyle = color;

        // Layer 1: 外部神聖格線
        ctx.lineWidth = 3;
        ctx.globalAlpha = 0.8;
        HexGeometry.traceRotatedHex(ctx, 0, 0, ultSize, rot, true);
        ctx.stroke();

        // Layer 2: 內部符文環 (虛線幾何)
        ctx.save();
        ctx.lineWidth = 1;
        ctx.setLineDash([12, 8]);
        ctx.globalAlpha = 0.5;
        HexGeometry.traceRotatedHex(ctx, 0, 0, ultSize * 0.85, -rot * 0.8, true);
        ctx.stroke();
        ctx.restore();

        // Layer 3: 中心匯聚點
        ctx.globalAlpha = 0.3 + Math.sin(t * 15) * 0.2;
        ctx.fillStyle = color;
        HexGeometry.traceRotatedHex(ctx, 0, 0, ultSize * 0.4, rot * 4, true);
        ctx.fill();

        // 4. 垂直能量柱投影
        const pillarH = 150 * progress;
        if (pillarH > 5) {
            ctx.fillStyle = color;
            const points = HexGeometry.getVertices(ultSize * 0.7, true);
            points.forEach((p, i) => {
                if (i % 2 === 0) {
                    const alpha = (0.2 + 0.3 * Math.sin(t * 8 + i)) * progress;
                    ctx.globalAlpha = alpha;
                    ctx.fillRect(p.x - 1, p.y - pillarH, 2, pillarH);
                }
            });
        }

        ctx.restore();
    },

    /**
     * 繪製 AOE 擴張波紋 (Vector Ripple)
     */
    drawAoeExpansion(ctx: CanvasRenderingContext2D, x: number, y: number, color: string, progress: number, rangeInTiles: number) {
        ctx.save();
        ctx.translate(x, y + AURA_FLOOR_LIFT - 0.5); // 稍微再高一點避免與法陣重疊

        // 數學半徑：根據網格尺寸精確映射
        const maxPixelRadius = rangeInTiles * HEX_SIZE;
        const easedRadius = maxPixelRadius * (1 - Math.pow(1 - progress, 4));

        ctx.strokeStyle = color;
        ctx.fillStyle = color;

        // 1. 波導前端
        ctx.beginPath();
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = (1 - progress) * 0.7;
        HexGeometry.traceHex(ctx, 0, 0, easedRadius, true);
        ctx.stroke();

        // 2. 內部漫反射
        ctx.globalAlpha = (1 - progress) * 0.08;
        ctx.fill();

        ctx.restore();
    },

    drawRisingParticles(ctx: CanvasRenderingContext2D, color: string, progress: number, t: number) {
        ctx.fillStyle = color;
        const count = 3;
        for(let i=0; i<count; i++) {
            const offset = i * (Math.PI * 2 / count);
            const cycle = (t * 2.5 + offset) % 1; 

            const h = cycle * 70;
            const r = (1 - cycle) * 35;
            const angle = t * 5 + offset;

            const px = Math.cos(angle) * r;
            const py = (Math.sin(angle) * r * 0.5) - h; 

            const alpha = Math.sin(cycle * Math.PI) * 0.8;
            ctx.globalAlpha = alpha;

            ctx.beginPath(); 
            ctx.arc(px, py, 1.5, 0, Math.PI*2); 
            ctx.fill();
        }
    }
};

import { Agent, GameEngine } from "../../game";
import { AnimState } from "../../../types";

export class CastingEngine {

    public updateCasting(a: Agent, dt: number, engine: GameEngine, onComplete: (a: Agent) => void) {
        // 1. 硬控場檢查 (Interrupt Priority)
        const isHardCC = a.stunTimer > 0 || a.banished || a.fearTimer > 0 || a.hp <= 0;

        if (isHardCC) {
            this.handleInterruption(a, engine);
            return;
        }

        if (a.silenceTimer > 0) {
            const currentSkill = a.castingSkillIdx !== -1 ? a.skills[a.castingSkillIdx] : null;
            if (currentSkill && currentSkill.tag !== 'BASIC') {
                this.handleInterruption(a, engine);
                return;
            }
        }

        // 2. 詠唱進度積分
        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        if (a.castTimer <= 0) {
            onComplete(a);
            this.resetCaster(a);
        }
    }

    private handleInterruption(a: Agent, engine: GameEngine) {
        const skillIdx = a.castingSkillIdx;
        if (skillIdx !== -1 && a.castTimer > 0 && a.skills[skillIdx]) {
            const s = a.skills[skillIdx]!;
            if (s.tag !== 'BASIC') {
                // 計算進度比：進度越高，中斷爆炸越強
                const progressPct = 1 - (a.castTimer / s.cast);

                engine.log(a, 'CC', '中斷', s.name, `詠唱被打斷 (進度: ${Math.floor(progressPct * 100)}%)`);

                // 傳遞精確的 3D 位置與進度參數
                engine.events.push({ 
                    type: 'CAST_BREAK', 
                    pos: { x: a.px, y: a.py }, 
                    value: progressPct, // 這裡重用 value 傳遞進度
                    color: s.color, 
                    skill: s 
                });
            }
        }
        this.resetCaster(a);
        a.setAnim(AnimState.IDLE); 
    }

    private resetCaster(a: Agent) {
        a.castingSkillIdx = -1;
        a.castTimer = 0;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.COMBAT_IDLE);
    }
}

import { GameEvent } from "../../../../types";
import { GameEngine } from "../../../game";
import { VFXSystem } from "../../vfx";
import { CameraSystem } from "../../CameraSystem";
import { Point3D } from "../EventVFXMapper";
import { UnitShatter } from "../effects/UnitShatter";

export class UnitVFXHandler {

    public static handle(event: GameEvent, engine: GameEngine, vfx: VFXSystem, camera: CameraSystem, origin: Point3D, groundZ: number) {

        if (event.type === 'DEATH') {
            const dAgent = engine.agents.find(a => a.id === event.sourceId);
            if (dAgent) {
                UnitShatter.spawn(vfx, origin.x, origin.y, origin.z, dAgent.team, dAgent.role, dAgent.physics.vx, dAgent.physics.vy);
            }
            camera.addTrauma(0.1);
            return;
        }

        if (event.type === 'SPAWN') {
            vfx.playEffect('FX_TELEPORT', origin.x, origin.y, groundZ, event.color, groundZ);
            return;
        }

        if (event.type === 'CAST_BREAK') {
            // 進度加成：詠唱越接近完成，爆炸效果越大 (0.5 ~ 1.5 倍)
            const progress = event.value || 0.1;
            const powerScale = 0.5 + progress;

            // 播放中斷碎裂特效
            vfx.playEffect('FX_CAST_BREAK', origin.x, origin.y, origin.z, event.color);

            // 奧義被斷的懲罰性視覺反饋
            if (event.skill && event.skill.tag === 'ULT') {
                camera.addTrauma(0.5 * powerScale);
                // 額外的全場閃光 (White Wash)
                vfx.playEffect('FX_HIT_GENERIC', origin.x, origin.y, origin.z, '#ffffff');
            } else {
                camera.addTrauma(0.2 * powerScale); 
            }
            return;
        }
    }
}

