import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_SCALE } from "../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { SpriteManager } from "../../../sprites";
import { VisualMath } from "../../../math/VisualMath";

export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, pz: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number
    ) {
        ctx.save(); 

        // 1. 獲取身體中心視覺 Y 軸 (SSOT)
        const bodyY = VisualMath.getVisualBodyCenterY(py, pz);
        ctx.translate(px, bodyY); 

        // 2. 核心受擊幾何處理 (Juice Math)
        let hitBrightness = 0;
        let squashX = 1.0;
        let squashY = 1.0;

        if (agent.hitFlashTimer > 0 && !isSilhouette) {
            const trauma = agent.hitFlashTimer / 0.2; // 歸一化進度
            // 數學擠壓：受擊時垂直縮短，水平伸長
            squashY = 1.0 - (trauma * 0.25);
            squashX = 1.0 + (trauma * 0.15);
            // 亮度震盪函數 (高頻率 40Hz)
            hitBrightness = 100 + Math.sin(t * 40) * 50;
        }

        ctx.scale(UNIT_SCALE * squashX, UNIT_SCALE * squashY);
        ctx.rotate(agent.physics.angle); 

        // 3. 基礎呼吸與浮動
        let bodyFloat = 0; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat = Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat = Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        // 4. 進場縮放動畫
        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= eased;
        }

        // 5. 狀態濾鏡應用
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(70%)'; 
        } else if (hitBrightness > 0) {
             ctx.filter = `brightness(${hitBrightness}%) contrast(120%)`;
        }

        // 6. 飛行與特殊模型渲染
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            UnitFlightPainter.drawFlightVFX(ctx, agent, t);
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -64, 96, 128);
                ctx.restore();
            }
        }

        ctx.restore(); 
    }
};

import { GameEvent } from "../../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../../vfx";
import { CameraSystem } from "../../CameraSystem";
import { Point3D } from "../EventVFXMapper";
import { VFX_REGISTRY } from "../../../../data/vfx/VFXRegistry";
import { Vector } from "../../../utils";

export class CombatVFXHandler {

    public static handle(event: GameEvent, vfx: VFXSystem, camera: CameraSystem, target: Point3D, groundZ: number) {
        const damage = Math.abs(event.value || 0);
        const isCrit = damage > 150;
        const isMassive = damage > 400;

        let intensity = 1.0;
        if (isCrit) intensity = 1.6;
        if (isMassive) intensity = 2.5;

        if (event.type === 'DAMAGE') {
            if (!event.skill?.projectileSpeed) {
                if (event.skill?.ccType !== 'DOT') {
                    // 核心受擊：播放命中特效
                    this.playImpact(event, vfx, target, groundZ, intensity);
                    camera.addTrauma(isMassive ? 0.45 : (isCrit ? 0.3 : 0.12));
                } else {
                    vfx.playEffect('FX_STATUS_BURN_LOOP', target.x, target.y, target.z, event.color);
                }
            }
            return;
        }

        if (event.type === 'PROJECTILE_HIT') {
            if (event.skill?.type !== 'AOE') {
                this.playImpact(event, vfx, target, groundZ, intensity);
                camera.addTrauma(0.2 * intensity); 
            } else {
                vfx.playEffect('FX_HIT_GENERIC', event.pos.x, event.pos.y, target.z, event.skill?.color, groundZ);
            }
            return;
        }

        if (event.type === 'IMPACT_AOE') {
            // 強制對齊地面 + 4px 抬升解決 Z-fighting
            const impactPoint = { x: event.pos.x, y: event.pos.y, z: groundZ + 4 };
            this.playImpact(event, vfx, impactPoint, groundZ, intensity * 1.2);
            camera.addTrauma(0.35 * intensity);
            return;
        }
    }

    private static playImpact(event: GameEvent, vfx: VFXSystem, target: Point3D, groundZ: number, scale: number = 1.0) {
        const skill = event.skill;
        const color = event.color || '#fff';

        let effectId = 'FX_HIT_GENERIC';
        if (skill && skill.visualHitEffect && VFX_REGISTRY[skill.visualHitEffect]) {
            effectId = skill.visualHitEffect;
        }

        // 1. 基礎命中粒子
        vfx.playEffect(effectId, target.x, target.y, target.z, color, groundZ);

        // 2. TA 額外加成：重擊閃光
        if (scale > 1.8) {
            const flash = vfx.state.getParticle();
            flash.type = 'GLOW';
            flash.x = target.x; flash.y = target.y; flash.z = target.z;
            flash.size = 120 * scale;
            flash.color = '#ffffff';
            flash.life = 0.08; flash.maxLife = 0.08;
            flash.blendMode = 'lighter';
            vfx.state.particles.push(flash);
        }

        // 3. 散射碎片 (如果非持續性傷害)
        if (event.skill?.ccType !== 'DOT') {
            const count = Math.floor(3 * scale);
            for(let i=0; i<count; i++) {
                const p = vfx.state.getParticle();
                p.x = target.x; p.y = target.y; p.z = target.z;
                p.type = 'CHIP';
                p.color = color;
                p.size = 2 + Math.random() * 4;
                const angle = Math.random() * Math.PI * 2;
                const force = 150 + Math.random() * 300;
                p.vx = Math.cos(angle) * force;
                p.vy = Math.sin(angle) * force;
                p.vz = 200 + Math.random() * 400;
                p.gravity = 3000;
                p.life = 0.4 + Math.random() * 0.4;
                p.maxLife = p.life;
                vfx.state.particles.push(p);
            }
        }
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill, AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { DamageCalculator } from "./DamageCalculator";
import { CCManager } from "./CCManager";
import { HazardManager } from "./HazardManager";
import { PhysicsEngine } from "../../physics/PhysicsEngine";
import { COMBAT_PARAM } from "../../../constants";

export class SkillExecutor {

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        let targets: Agent[] = [];
        let origin = {x: source.px, y: source.py}; 
        let targetHex = source.targetHex || (source.target ? {q: source.target.q, r: source.target.r} : {q: source.q, r: source.r});

        const impactCells = engine.movement.targeting.getImpactArea(source, targetHex, skill, engine);

        if (skill.type === 'AOE' || impactCells.length > 1) {
            impactCells.forEach(cell => {
                const u = engine.getAgentAt(cell.q, cell.r);
                if (u && u.hp > 0 && !u.banished) {
                    if (skill.power >= 0 && u.team !== source.team) targets.push(u);
                    else if (skill.power < 0 && u.team === source.team) targets.push(u);
                }
            });

            const p = HexUtils.toPx(targetHex.q, targetHex.r, engine.mapConfig);
            origin = { x: p.x, y: p.y };
            engine.events.push({ type: 'IMPACT_AOE', pos: origin, skill, color: skill.color });
            HazardManager.spawnHazards(source, impactCells, skill, engine);
        } else {
            if (source.target && source.target.hp > 0 && !source.target.banished) {
                const effRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                if (HexUtils.dist(source, source.target) <= effRange) {
                    targets.push(source.target);
                }
            }
        }

        if (targets.length === 0 && skill.power <= 0 && skill.type === 'SINGLE') {
            targets.push(source);
        }

        targets.forEach(t => {
            const dist = HexUtils.dist(source, t);
            if (dist > 1) {
                engine.events.push({ type: 'VISUAL_BEAM', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            } else {
                engine.events.push({ type: 'VISUAL_SLASH', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            }
            this.resolveHit(source, t, skill, origin, engine);
        });

        if (skill.tag !== 'BASIC') {
            engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
        }
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        const result = DamageCalculator.calculate(source, target, skill);
        if (result.isMiss) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "MISS", color: "#94a3b8" });
            return;
        }

        const oldHp = Math.ceil(target.hp);
        if (result.shieldAbsorb > 0) target.shield -= result.shieldAbsorb;

        target.hp = Math.min(target.maxHp, target.hp + result.finalValue);

        if (result.vampAmount > 0 && source.hp > 0) {
            source.hp = Math.min(source.maxHp, source.hp + result.vampAmount);
            engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: result.vampAmount, color: '#86efac' });
        }

        if (result.finalValue < 0) { 
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = COMBAT_PARAM.HIT_FLASH_DURATION; // 使用常量統一管理

            // 物理衝量計算：基於傷害量的對數擴展，防止數值過大導致單位飛出地圖
            const originPx = origin ? origin : {x: source.px, y: source.py};
            const damageForce = Math.min(600, 100 + Math.abs(result.finalValue) * 1.5);
            PhysicsEngine.applyImpulse(target, originPx, damageForce, 0.4);
        }

        engine.events.push({
            type: result.finalValue < 0 ? 'DAMAGE' : 'HEAL',
            pos: { x: target.px, y: target.py },
            value: result.finalValue,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        CCManager.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        CCManager.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        if (oldHp > 0 && target.hp <= 0) {
            engine.events.push({ type: 'KILL', pos: { x: target.px, y: target.py }, sourceId: source.id, targetId: target.id });
        }
    }
}

import { Agent, GameEngine } from "../game";
import { MovementType, AnimState } from "../../types";
import { HexUtils } from "../utils";
import { PHYSICS } from "../../constants";

export class PhysicsEngine {
    public static applyImpulse(target: Agent, origin: {x: number, y: number}, force: number, randomness: number = 0) {
        const dx = target.px - origin.x;
        const dy = target.py - origin.y;
        const len = Math.sqrt(dx * dx + dy * dy);
        const effectiveForce = Math.min(PHYSICS.TERMINAL_VELOCITY_IMPULSE, Math.max(50, force));
        let vx = 0, vy = 0;
        if (len <= 0.1) {
            const ang = Math.random() * Math.PI * 2;
            vx = Math.cos(ang) * effectiveForce;
            vy = Math.sin(ang) * effectiveForce;
        } else {
            vx = (dx / len) * effectiveForce;
            vy = (dy / len) * effectiveForce;
        }
        target.physics.vx += vx;
        target.physics.vy += vy;
        if (randomness > 0) target.physics.vAngle += (Math.random() - 0.5) * randomness;
    }

    public update(a: Agent, dt: number, engine: GameEngine) {
        if (a.fullyDead) return;
        const isDead = a.hp <= 0;

        // TA 優化：增加 Stiffness 使受擊後恢復更迅速
        const stiffness = isDead ? 0 : PHYSICS.STIFFNESS_ALIVE * 1.2;
        const damping = PHYSICS.DAMPING_ALIVE * 1.1; 

        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        const isAirborne = a.physics.z > 0;
        const isFlying = a.movementType === MovementType.FLYING && !isDead;
        const isDisabled = a.stunTimer > 0 || a.visualStatus === 'FROZEN' || a.visualStatus === 'POLYMORPH';

        if (isFlying && !isDisabled) {
            const hoverHeight = 55, hoverFreq = 2.5; 
            const targetZ = hoverHeight + Math.sin(engine.battleTime * hoverFreq) * 5;
            const dz = targetZ - a.physics.z;
            a.physics.vz += dz * 5 * dt;
            a.physics.vz *= 0.92;
        } else if (isAirborne || a.physics.z > 0.1) {
            a.physics.vz -= PHYSICS.GRAVITY * dt;
        }

        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        if (a.physics.z < 0) {
            a.physics.z = 0;
            if (a.physics.vz < -PHYSICS.SAFE_FALL_VELOCITY) {
                const impactSpeed = Math.abs(a.physics.vz);
                if (!isDead) {
                    const velocityOverhead = impactSpeed - PHYSICS.SAFE_FALL_VELOCITY;
                    const scaling = PHYSICS.FATAL_FALL_VELOCITY - PHYSICS.SAFE_FALL_VELOCITY;
                    const pct = Math.min(1.0, velocityOverhead / scaling);
                    const rawDmg = Math.floor(a.maxHp * pct) + PHYSICS.FALL_DAMAGE_MIN;
                    a.hp = Math.max(0, a.hp - rawDmg);
                    engine.events.push({ type: 'DAMAGE', pos: {x: a.px, y: a.py}, value: -rawDmg, color: '#ef4444', text: "墜落" });
                    engine.log(a, 'HAZARD', '墜落', '地面', `受到墜落傷害 ${rawDmg}`);
                    if (engine.renderer) engine.renderer.camera.addTrauma(pct * 0.5);
                    if (a.hp <= 0) engine.agentManager.handleDeadState(a, engine);
                    else a.setAnim(AnimState.HIT);
                }
                a.physics.vz = -a.physics.vz * 0.3;
                a.physics.vx *= 0.5; a.physics.vy *= 0.5; a.physics.vAngle *= 0.5;
            } else {
                a.physics.vz = 0;
            }
        }

        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px, dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;
            if (distSq > 0.5) {
                const driftSpeed = PHYSICS.DRIFT_SPEED * dt; 
                a.px += dx * driftSpeed; a.py += dy * driftSpeed;
                if (distSq < 2) { a.px = targetPos.x; a.py = targetPos.y; }
            } else {
                a.px = targetPos.x; a.py = targetPos.y;
            }
        }
    }
}

import { Point } from "../../types";
import { Vector } from "../utils";

export interface Point3D { x: number; y: number; z: number; }

/**
 * 飛行物 BALLISTICS 幾何真理 - v13.0
 * 所有計算皆基於時間進度 t [0..1]
 */
export const TrajectoryMath = {

    /**
     * 線性軌跡及其一階導數
     */
    linear: (start: Point3D, end: Point3D, t: number): Point3D => {
        return {
            x: start.x + (end.x - start.x) * t,
            y: start.y + (end.y - start.y) * t,
            z: start.z + (end.z - start.z) * t
        };
    },

    /**
     * 解析拋物線軌跡 (Parabolic Arc)
     * $Z(t)$ 由起始高度、結束高度與中點拱高 $h$ 構成
     */
    parabolic: (start: Point3D, end: Point3D, t: number, arcHeight: number): Point3D => {
        const x = start.x + (end.x - start.x) * t;
        const y = start.y + (end.y - start.y) * t;

        // 核心彈道公式：線性高度 + 拋物線偏移
        const linearZ = start.z * (1 - t) + end.z * t;
        const arcZ = 4 * arcHeight * t * (1 - t);

        return { x, y, z: linearZ + arcZ };
    },

    /**
     * 正弦擺動軌跡 (用於魔法彈/混亂箭)
     */
    wobble: (start: Point3D, end: Point3D, t: number, amp: number, freq: number): Point3D => {
        const base = TrajectoryMath.linear(start, end, t);
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const len = Math.sqrt(dx * dx + dy * dy);

        if (len < 0.001) return base;

        // 計算法線向量以施加擺動偏移
        const nx = -dy / len;
        const ny = dx / len;
        const wave = Math.sin(t * Math.PI * 2 * freq) * amp;

        return {
            x: base.x + nx * wave,
            y: base.y + ny * wave,
            z: base.z
        };
    },

    /**
     * 計算 3D 空間中的切向向量 (用於解算指向旋轉)
     */
    getTangent: (func: (t: number) => Point3D, t: number): Point3D => {
        const eps = 0.01;
        const p1 = func(t);
        const p2 = func(Math.min(1.0, t + eps));
        return {
            x: p2.x - p1.x,
            y: p2.y - p1.y,
            z: p2.z - p1.z
        };
    }
};

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { RenderList, RenderOpType } from "../../../renderers/RenderList";
import { getTransitionOffset } from "../utils";
import { Projectile } from "../../../../types";
import { PROJECTILE_VISUALS, DEFAULT_PROJECTILE, ProjectileVisualDef } from "../../../../data/vfx/projectile_visuals";
import { TrajectoryMath, Point3D } from "../../../math/TrajectoryMath";
import { VisualMath } from "../../../math/VisualMath";
import { ISO_SCALE_Y } from "../../../../constants";

export const ProjectileRenderer = {
    submit(
        renderList: RenderList,
        engine: GameEngine,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        const now = engine.battleTime;

        for (const p of engine.projectiles) {
            if (!p.active) continue;

            const lookupKey = p.skill.visualProjectileEffect || p.skill.id || p.skill.visual || 'BOLT';
            const def: ProjectileVisualDef = PROJECTILE_VISUALS[lookupKey] || DEFAULT_PROJECTILE;

            // 1. 解析起始與終點 (SSOT)
            const startPoint: Point3D = { x: p.startX, y: p.startY, z: p.startZ || 0 };
            const targetPoint = VisualMath.resolveTargetPoint(p.targetId, engine);

            // 安全邊界處理
            let endPoint: Point3D = targetPoint;
            if (endPoint.z < -9000) {
                const h = engine.map.getTerrainHeight(HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig).q, HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig).r);
                endPoint = { x: p.targetPos.x, y: p.targetPos.y, z: h + 25 };
            }

            // 2. 計算精確時間進度 (亞像素平滑)
            const totalDist = Vector.dist({x: startPoint.x, y: startPoint.y}, {x: endPoint.x, y: endPoint.y});
            const speed = Math.max(200, p.speed);
            const duration = totalDist / speed;
            const age = now - p.createdAt;
            const t = Math.min(1.0, age / duration);

            // 3. 軌道函數閉包 (用於切向解算)
            const getPosAt = (time: number): Point3D => {
                if (def.trajectory === 'ARC') return TrajectoryMath.parabolic(startPoint, endPoint, time, def.arcHeight || 120);
                if (def.trajectory === 'WOBBLE') return TrajectoryMath.wobble(startPoint, endPoint, time, def.wobbleAmp || 15, def.wobbleFreq || 2);
                return TrajectoryMath.linear(startPoint, endPoint, time);
            };

            const currentPos3D = getPosAt(t);
            const tangent = TrajectoryMath.getTangent(getPosAt, t);

            // 4. 等角透視轉換 (Unique Math)
            // 視覺 Y 變化 = (dy * ISO_SCALE) - dz
            const visAngle = Math.atan2(tangent.y * ISO_SCALE_Y - tangent.z, tangent.x);

            const transOffset = getTransitionOffset(currentPos3D.x, currentPos3D.y, engine.mapConfig, transitionT, transitionPhase);
            const visX = currentPos3D.x;
            const visY = currentPos3D.y * ISO_SCALE_Y - currentPos3D.z + transOffset;

            // 5. 提交渲染指令
            const op = renderList.next();
            op.type = RenderOpType.PROJECTILE;
            op.y = currentPos3D.y; // 排序基於邏輯 Y
            op.z = currentPos3D.z;

            op.pVisX = visX;
            op.pVisY = visY;
            op.pAngle = visAngle;
            op.pSkillVis = def.spriteKey || p.skill.visual || 'BOLT';
            op.pColor = def.colorOverride || p.skill.color;
            op.pIsUlt = p.skill.tag === 'ULT';
            op.pSpin = def.spinSpeed ? (age * def.spinSpeed) : 0;

            // 6. 解析尾跡 (Analytic Trails)
            op.pTrail = [];
            const trailSamples = def.trailLength || 0;
            if (trailSamples > 0) {
                const step = 0.03; 
                for(let i = 1; i <= trailSamples; i++) {
                    const tPast = Math.max(0, t - i * step);
                    const past3D = getPosAt(tPast);
                    const pastVisY = past3D.y * ISO_SCALE_Y - past3D.z + transOffset;
                    op.pTrail.push({ x: past3D.x, y: pastVisY });
                    if (tPast <= 0) break;
                }
            }
        }
    }
};

import { RenderOp } from "./RenderList";
import { AssetManager } from "../assets";

/**
 * 高階飛行物繪製器 v13.0
 */
export const ProjectileDrawer = {
    draw(ctx: CanvasRenderingContext2D, op: RenderOp, globalTime: number) {
        const isRay = op.pSkillVis === 'BEAM'; 

        // 1. 亞像素座標平滑處理
        const drawX = op.pVisX;
        const drawY = op.pVisY;

        // 2. 尾跡渲染 (解析漸變)
        if (op.pTrail && op.pTrail.length > 1) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.beginPath();
            ctx.moveTo(drawX, drawY);

            for(let i=0; i < op.pTrail.length; i++) {
                ctx.lineTo(op.pTrail[i].x, op.pTrail[i].y);
            }

            ctx.strokeStyle = op.pColor;
            ctx.lineWidth = op.pIsUlt ? 6 : 3;
            ctx.globalAlpha = 0.5;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.stroke();
            ctx.restore();
        }

        // 3. 核心精靈渲染
        ctx.save();
        ctx.translate(drawX, drawY);

        // 應用解析旋轉與自旋
        if (op.pSpin !== 0) ctx.rotate(op.pSpin); 
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img) {
            const scale = (op.pIsUlt ? 1.6 : 1.1);
            ctx.scale(scale, scale);

            // Pass 1: 基礎投影 (色彩填充)
            ctx.globalAlpha = 1.0;
            ctx.drawImage(img, -32, -32, 64, 64);

            // Pass 2: 能量發光 (Additive Bloom)
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.6 + Math.sin(globalTime * 15) * 0.2;
            ctx.drawImage(img, -36, -36, 72, 72);
        }

        ctx.restore();

        // 4. 重擊點補償 (如果為奧義)
        if (op.pIsUlt) {
            ctx.save();
            ctx.translate(drawX, drawY);
            ctx.globalCompositeOperation = 'screen';
            const pulse = 15 + Math.sin(globalTime * 20) * 5;
            const grad = ctx.createRadialGradient(0,0,0, 0,0, pulse);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0,0, pulse, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }
    }
};

import { Agent, GameEngine } from "../../game";
import { Projectile, Skill, Team } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { SkillExecutor } from "./SkillExecutor";
import { PROJECTILE_VISUALS } from "../../../data/vfx/projectile_visuals";
import { VisualMath } from "../../math/VisualMath";
import { HazardManager } from "./HazardManager";
import { VISUAL_ANCHORS } from "../../../constants";

export class ProjectileSystem {
    private pool: Projectile[] = [];

    constructor() {
        for (let i = 0; i < 60; i++) {
            this.pool.push(this.createEmptyProjectile());
        }
    }

    public update(dt: number, engine: GameEngine, skillExecutor: SkillExecutor) {
        const list = engine.projectiles;
        for (let i = list.length - 1; i >= 0; i--) {
            const p = list[i];
            if (!p.active) { this.removeProjectile(i, engine); continue; }

            // 1. 生命週期與進度計算
            const targetPoint = VisualMath.resolveTargetPoint(p.targetId, engine);
            if (targetPoint.z > -9000) {
                p.targetPos = { x: targetPoint.x, y: targetPoint.y };
            }

            const distSq = (p.targetPos.x - p.x)**2 + (p.targetPos.y - p.y)**2;
            const speed = Math.max(300, p.speed);
            const moveStep = speed * dt;

            // 2. 命中判定 (3D 球體近似)
            // 由於採用解析座標渲染，System 只需負責邏輯位置的推進
            const dir = Vector.normalize(Vector.sub(p.targetPos, {x: p.x, y: p.y}));

            if (distSq <= moveStep * moveStep || distSq < 400) { // 20px radius
                this.handleImpact(p, engine, skillExecutor);
                this.release(p);
                this.removeProjectile(i, engine);
            } else {
                p.x += dir.x * moveStep;
                p.y += dir.y * moveStep;
            }
        }
    }

    private handleImpact(p: Projectile, engine: GameEngine, skillExecutor: SkillExecutor) {
        const source = engine.agents.find(a => a.id === p.sourceId);
        const hitPos = p.targetPos;

        if (p.skill.type === 'AOE') {
            const radius = p.skill.aoeRadius || 1;
            const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);

            engine.agents.forEach(t => {
                if (t.team !== p.team && t.hp > 0 && !t.banished) {
                    if (HexUtils.dist(hitHex, t) <= radius) {
                        if (source) skillExecutor.resolveHit(source, t, p.skill, hitPos, engine);
                    }
                }
            });

            if (source) {
                HazardManager.spawnHazards(source, HexUtils.range(hitHex, radius), p.skill, engine);
            }
            engine.events.push({ type: 'IMPACT_AOE', pos: hitPos, skill: p.skill, color: p.skill.color });
        } else {
            const target = engine.agents.find(a => a.id === p.targetId);
            if (target && target.hp > 0 && !target.banished) {
                if (source) skillExecutor.resolveHit(source, target, p.skill, undefined, engine);
            }
        }
        engine.events.push({ type: 'PROJECTILE_HIT', pos: hitPos, skill: p.skill });
    }

    private removeProjectile(idx: number, engine: GameEngine) {
        const last = engine.projectiles.pop();
        if (last && idx < engine.projectiles.length) {
            engine.projectiles[idx] = last;
        }
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        const target = skill.type === 'AOE' ? source.targetHex || source.target : source.target;
        if (!target) return;

        const targetId = (target as any).id || `ground-${(target as any).q},${(target as any).r}`;
        const targetPos = (target as any).px !== undefined ? {x:(target as any).px, y:(target as any).py} : HexUtils.toPx((target as any).q, (target as any).r, engine.mapConfig);

        const launchAnchor = VisualMath.getUnitAnchor(source, engine);
        const p = this.pool.pop() || this.createEmptyProjectile();

        p.active = true;
        p.createdAt = engine.battleTime;
        p.lifespan = 5.0;
        p.id = Math.random().toString(36).substr(2, 6);
        p.x = source.px;
        p.y = source.py;
        p.startX = source.px;
        p.startY = source.py;
        p.startZ = launchAnchor.z;
        p.targetId = targetId;
        p.targetPos = targetPos;
        p.speed = skill.projectileSpeed || 800;
        p.skill = skill;
        p.sourceId = source.id;
        p.team = source.team;
        p.trail = [];

        engine.projectiles.push(p);
        engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: targetId });
    }

    private release(p: Projectile) {
        p.active = false;
        p.trail = [];
        this.pool.push(p);
    }

    private createEmptyProjectile(): Projectile {
        return {
            id: '', active: false, createdAt: 0, lifespan: 0,
            x: 0, y: 0, startX: 0, startY: 0, startZ: 0,
            targetId: '', targetPos: {x: 0, y: 0},
            speed: 0, skill: {} as Skill, sourceId: '', team: Team.BLUE,
            trail: []
        };
    }
}

import { Point } from "../../types";

export interface Point3D { x: number; y: number; z: number; }

/**
 * 飛行幾何真理庫 v14.0 - Analytic Ballistics
 */
export const TrajectoryMath = {

    /**
     * 線性插值座標 (解析解)
     */
    linear: (start: Point3D, end: Point3D, t: number): Point3D => {
        return {
            x: start.x + (end.x - start.x) * t,
            y: start.y + (end.y - start.y) * t,
            z: start.z + (end.z - start.z) * t
        };
    },

    /**
     * 解析拋物線 (Parabolic Arc)
     * 計算在進度 t 時的 3D 座標，h 為頂點拱高
     */
    parabolic: (start: Point3D, end: Point3D, t: number, h: number): Point3D => {
        const x = start.x + (end.x - start.x) * t;
        const y = start.y + (end.y - start.y) * t;
        const linearZ = start.z * (1 - t) + end.z * t;
        // 拋物線高度公式: 4h * t * (1-t)
        const arcZ = 4 * h * t * (1 - t);
        return { x, y, z: linearZ + arcZ };
    },

    /**
     * 螺旋擺動軌跡 (Wobble Path)
     */
    wobble: (start: Point3D, end: Point3D, t: number, amp: number, freq: number): Point3D => {
        const base = TrajectoryMath.linear(start, end, t);
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < 1) return base;

        // 計算垂直於運動方向的法線向量
        const nx = -dy / dist;
        const ny = dx / dist;
        const wave = Math.sin(t * Math.PI * 2 * freq) * amp;

        return {
            x: base.x + nx * wave,
            y: base.y + ny * wave,
            z: base.z + Math.cos(t * Math.PI * 2 * freq) * amp * 0.5
        };
    },

    /**
     * 計算解析解在一階導數下的切向角
     * 會考慮 Z 軸變化對等角投影 (Y 軸壓縮) 的視覺影響
     */
    getProjectedAngle: (func: (t: number) => Point3D, t: number, isoScaleY: number): number => {
        const eps = 0.01;
        const p1 = func(t);
        const p2 = func(Math.min(1.0, t + eps));

        const dx = p2.x - p1.x;
        const dy = p2.y - p1.y;
        const dz = p2.z - p1.z;

        // 視覺 Y 變化量 = (物理 Y * ISO 壓縮) - 高度變化 Z
        const vy = dy * isoScaleY - dz;
        return Math.atan2(vy, dx);
    }
};

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { RenderList, RenderOpType } from "../../../renderers/RenderList";
import { getTransitionOffset } from "../utils";
import { Projectile } from "../../../../types";
import { PROJECTILE_VISUALS, DEFAULT_PROJECTILE, ProjectileVisualDef } from "../../../../data/vfx/projectile_visuals";
import { TrajectoryMath, Point3D } from "../../../math/TrajectoryMath";
import { VisualMath } from "../../../math/VisualMath";
import { ISO_SCALE_Y } from "../../../../constants";

export const ProjectileRenderer = {
    submit(
        renderList: RenderList,
        engine: GameEngine,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        const now = engine.battleTime;

        for (const p of engine.projectiles) {
            if (!p.active) continue;

            const def: ProjectileVisualDef = PROJECTILE_VISUALS[p.skill.visualProjectileEffect || p.skill.visual || 'BOLT'] || DEFAULT_PROJECTILE;

            // 1. 建立解析座標函數
            const startP: Point3D = { x: p.startX, y: p.startY, z: p.startZ || 30 };
            const targetP = VisualMath.resolveTargetPoint(p.targetId, engine);

            // 安全邊界處理
            let endP: Point3D = targetP;
            if (endP.z < -9000) {
                 const h = engine.map.getTerrainHeight(HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig).q, HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig).r);
                 endP = { x: p.targetPos.x, y: p.targetPos.y, z: h + 25 };
            }

            const totalDist = Math.sqrt((endP.x - startP.x)**2 + (endP.y - startP.y)**2);
            const duration = totalDist / Math.max(200, p.speed);
            const age = now - p.createdAt;
            const t = Math.min(1.0, age / duration);

            const getPosAt = (progress: number) => {
                if (def.trajectory === 'ARC') return TrajectoryMath.parabolic(startP, endP, progress, def.arcHeight || 120);
                if (def.trajectory === 'WOBBLE') return TrajectoryMath.wobble(startP, endP, progress, def.wobbleAmp || 15, def.wobbleFreq || 2);
                return TrajectoryMath.linear(startP, endP, progress);
            };

            const pos3D = getPosAt(t);
            const visAngle = TrajectoryMath.getProjectedAngle(getPosAt, t, ISO_SCALE_Y);

            // 2. 計算視覺座標 (等角投影)
            const transOffset = getTransitionOffset(pos3D.x, pos3D.y, engine.mapConfig, transitionT, transitionPhase);
            const visX = pos3D.x;
            const visY = pos3D.y * ISO_SCALE_Y - pos3D.z + transOffset;

            // 3. 提交渲染指令
            const op = renderList.next();
            op.type = RenderOpType.PROJECTILE;

            // 核心優化：飛行物 Y 排序偏置。讓高速飛行物看起來在地形「之上」
            op.y = pos3D.y + 10; 
            op.z = pos3D.z + 500; // 給予極高的層級分數以防 Z-fighting

            op.pVisX = visX;
            op.pVisY = visY;
            op.pAngle = visAngle;
            op.pSkillVis = def.spriteKey || p.skill.visual || 'BOLT';
            op.pColor = p.skill.color;
            op.pIsUlt = p.skill.tag === 'ULT';
            op.pSpin = def.spinSpeed ? (age * def.spinSpeed) : 0;

            // 4. 解析尾跡採樣 (Analytic Trail Sampling)
            op.pTrail = [];
            const trailSamples = def.trailLength || 0;
            if (trailSamples > 0) {
                const step = 0.02; // 時間步長
                for (let i = 1; i <= trailSamples; i++) {
                    const tPast = Math.max(0, t - i * step);
                    const past3D = getPosAt(tPast);
                    const pastY = past3D.y * ISO_SCALE_Y - past3D.z + transOffset;
                    op.pTrail.push({ x: past3D.x, y: pastY });
                    if (tPast <= 0) break;
                }
            }
        }
    }
};

import { RenderOp } from "./RenderList";
import { AssetManager } from "../assets";

/**
 * 飛行物視覺呈現器 v14.0 - TA Visual Polish
 */
export const ProjectileDrawer = {
    draw(ctx: CanvasRenderingContext2D, op: RenderOp, globalTime: number) {
        const { pVisX: x, pVisY: y, pColor: color, pAngle: angle, pTrail: trail } = op;

        // 1. 渲染能量尾跡 (Analytic Gradient Trail)
        if (trail && trail.length > 1) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.beginPath();
            ctx.moveTo(x, y);

            for (let i = 0; i < trail.length; i++) {
                ctx.lineTo(trail[i].x, trail[i].y);
            }

            const trailGrad = ctx.createLinearGradient(x, y, trail[trail.length-1].x, trail[trail.length-1].y);
            trailGrad.addColorStop(0, color);
            trailGrad.addColorStop(1, 'transparent');

            ctx.strokeStyle = trailGrad;
            ctx.lineWidth = op.pIsUlt ? 8 : 3;
            ctx.globalAlpha = 0.6;
            ctx.lineCap = 'round';
            ctx.stroke();
            ctx.restore();
        }

        // 2. 主體精靈渲染
        ctx.save();
        ctx.translate(x, y);

        // 運動模糊模擬：根據速度向量進行視覺拉伸 (SSOT: 此處假設速度影響拉伸)
        const stretch = op.pIsUlt ? 1.5 : 1.15;
        if (op.pSpin !== 0) {
            ctx.rotate(op.pSpin);
        } else {
            ctx.rotate(angle);
            ctx.scale(stretch, 1.0 / stretch); // 體積守恆拉伸
        }

        const img = AssetManager.getProjectile(op.pSkillVis, color);
        if (img) {
            const scale = op.pIsUlt ? 1.8 : 1.2;

            // 底層：基礎色
            ctx.globalAlpha = 1.0;
            ctx.drawImage(img, -32 * scale, -32 * scale, 64 * scale, 64 * scale);

            // 頂層：動態發光 (Additive Pulse)
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.4 + Math.sin(globalTime * 20) * 0.2;
            ctx.drawImage(img, -36 * scale, -36 * scale, 72 * scale, 72 * scale);
        }

        ctx.restore();

        // 3. 亮點補償 (奧義專用)
        if (op.pIsUlt) {
            ctx.save();
            ctx.translate(x, y);
            ctx.globalCompositeOperation = 'screen';
            const flare = ctx.createRadialGradient(0,0,0, 0,0, 40);
            flare.addColorStop(0, '#fff');
            flare.addColorStop(0.3, color);
            flare.addColorStop(1, 'transparent');
            ctx.fillStyle = flare;
            ctx.beginPath(); ctx.arc(0,0, 40, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }
    }
};

import { Agent, GameEngine } from "../../game";
import { Projectile, Skill, Team } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { SkillExecutor } from "./SkillExecutor";
import { VisualMath } from "../../math/VisualMath";
import { HazardManager } from "./HazardManager";

export class ProjectileSystem {
    private pool: Projectile[] = [];

    constructor() {
        for (let i = 0; i < 60; i++) {
            this.pool.push(this.createEmptyProjectile());
        }
    }

    public update(dt: number, engine: GameEngine, skillExecutor: SkillExecutor) {
        const list = engine.projectiles;
        for (let i = list.length - 1; i >= 0; i--) {
            const p = list[i];
            if (!p.active) { this.removeProjectile(i, engine); continue; }

            // 1. 邏輯步進 (解析解座標同步)
            // 系統只負責檢查碰撞範圍，具體座標由解析公式計算
            const targetPoint = VisualMath.resolveTargetPoint(p.targetId, engine);
            if (targetPoint.z > -9000) p.targetPos = { x: targetPoint.x, y: targetPoint.y };

            const dx = p.targetPos.x - p.x;
            const dy = p.targetPos.y - p.y;
            const distSq = dx*dx + dy*dy;

            const moveStep = Math.max(300, p.speed) * dt;

            // 2. 命中判定
            if (distSq < (moveStep * moveStep * 2) || distSq < 400) {
                this.handleImpact(p, engine, skillExecutor);
                this.release(p);
                this.removeProjectile(i, engine);
            } else {
                const mag = Math.sqrt(distSq);
                p.x += (dx / mag) * moveStep;
                p.y += (dy / mag) * moveStep;
            }
        }
    }

    private handleImpact(p: Projectile, engine: GameEngine, skillExecutor: SkillExecutor) {
        const source = engine.agents.find(a => a.id === p.sourceId);
        const hitPos = p.targetPos;

        if (p.skill.type === 'AOE') {
            const radius = p.skill.aoeRadius || 1;
            const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);

            engine.agents.forEach(t => {
                if (t.team !== p.team && t.hp > 0 && !t.banished) {
                    if (HexUtils.dist(hitHex, t) <= radius) {
                        if (source) skillExecutor.resolveHit(source, t, p.skill, hitPos, engine);
                    }
                }
            });

            if (source) {
                HazardManager.spawnHazards(source, HexUtils.range(hitHex, radius), p.skill, engine);
            }
            engine.events.push({ type: 'IMPACT_AOE', pos: hitPos, skill: p.skill, color: p.skill.color });
        } else {
            const target = engine.agents.find(a => a.id === p.targetId);
            if (target && target.hp > 0 && !target.banished) {
                if (source) skillExecutor.resolveHit(source, target, p.skill, undefined, engine);
            }
        }
        engine.events.push({ type: 'PROJECTILE_HIT', pos: hitPos, skill: p.skill });
    }

    private removeProjectile(idx: number, engine: GameEngine) {
        const last = engine.projectiles.pop();
        if (last && idx < engine.projectiles.length) {
            engine.projectiles[idx] = last;
        }
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        const target = skill.type === 'AOE' ? (source.targetHex || source.target) : source.target;
        if (!target) return;

        const targetId = (target as any).id || `ground-${(target as any).q},${(target as any).r}`;
        const targetPos = (target as any).px !== undefined ? {x:(target as any).px, y:(target as any).py} : HexUtils.toPx((target as any).q, (target as any).r, engine.mapConfig);

        const launchAnchor = VisualMath.getUnitAnchor(source, engine);
        const p = this.pool.pop() || this.createEmptyProjectile();

        p.active = true;
        p.createdAt = engine.battleTime;
        p.lifespan = 5.0;
        p.id = Math.random().toString(36).substr(2, 6);
        p.x = source.px;
        p.y = source.py;
        p.startX = source.px;
        p.startY = source.py;
        p.startZ = launchAnchor.z;
        p.targetId = targetId;
        p.targetPos = targetPos;
        p.speed = skill.projectileSpeed || 800;
        p.skill = skill;
        p.sourceId = source.id;
        p.team = source.team;
        p.trail = [];

        engine.projectiles.push(p);
        engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: targetId });
    }

    private release(p: Projectile) {
        p.active = false;
        p.trail = [];
        this.pool.push(p);
    }

    private createEmptyProjectile(): Projectile {
        return {
            id: '', active: false, createdAt: 0, lifespan: 0,
            x: 0, y: 0, startX: 0, startY: 0, startZ: 0,
            targetId: '', targetPos: {x: 0, y: 0},
            speed: 0, skill: {} as Skill, sourceId: '', team: Team.BLUE,
            trail: []
        };
    }
}

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

// 唯一數學常數：解決幾何接縫與 Z-fighting
const WALL_OVERLAP_EPSILON = 1.0; 
const TOP_CAP_VISUAL_LIFT = -0.5; // 極微量抬升，確保頂面優先於牆面

export const TerrainRenderer = {
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        const visualTopY = -height;
        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // 1. 繪製垂直側牆 (物理地基)
        // 增加 WALL_OVERLAP_EPSILON 以確保牆面稍微高出頂面邊界，消除裂縫
        if (layout === 'FLAT') {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY - WALL_OVERLAP_EPSILON, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY - WALL_OVERLAP_EPSILON, theme.sideLight);
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY - WALL_OVERLAP_EPSILON, theme.sideDark);
        } else {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY - WALL_OVERLAP_EPSILON, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY - WALL_OVERLAP_EPSILON, theme.sideLight);

            // 尖頂中心縫補強
            ctx.strokeStyle = 'rgba(0,0,0,0.1)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(vertices[1].x, vertices[1].y);
            ctx.lineTo(vertices[1].x, vertices[1].y + visualTopY);
            ctx.stroke();
        }

        // 2. 繪製頂部六邊形面 (Top Surface)
        ctx.translate(0, visualTopY + TOP_CAP_VISUAL_LIFT);

        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;
        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // 頂部描邊 (Rim Light) - 強化幾何輪廓，減少平滑穿插感
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.0;
        ctx.globalAlpha = 0.6;
        ctx.stroke();

        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        }

        ctx.restore();
    },

    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);
        // 底座防穿插：確保側牆底部稍微沒入地平線以下
        ctx.lineTo(vBottom1.x, vBottom1.y + BASE_HEIGHT + 0.5); 
        ctx.closePath();
        ctx.fill();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        // 裝飾物座標必須嚴格隨頂面抬升
        const visualY = baseY - height + TOP_CAP_VISUAL_LIFT;
        if (type === 'FOREST' || type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

