    }
}

export class RenderList {
    public ops: RenderOp[] = [];
    public count: number = 0;
    private sortView: RenderOp[] = [];
    private capacity: number = 8000;

    constructor() {
        for(let i=0; i<this.capacity; i++) {
            const op = new RenderOp();
            this.ops.push(op);
            this.sortView.push(op); 
        }
    }

    public reset() {
        this.count = 0;
    }

    public next(): RenderOp {
        if (this.count >= this.ops.length) {
            for(let i=0; i<1000; i++) {
                const op = new RenderOp();
                this.ops.push(op);
                this.sortView.push(op);
            }
        }
        const op = this.ops[this.count++];
        op.clear(); 
        return op;
    }

    public sort() {
        if (this.count <= 1) return;
        for (let i = 0; i < this.count; i++) {
            const op = this.ops[i];

            /**
             * 唯一數學排序規範 v16.0 (Diamond Depth Sorting)
             * 
             * 1. 基底深度 (Base Depth): q + r 決定了在六邊形網格中的「排隊順序」。
             * 2. 高度偏置 (Height Bias): 瓦片本身的 Tier (th / BLOCK_HEIGHT)。
             * 3. 類別優先權 (Layer): 確保單位在瓦片頂面之上。
             */

            // 基礎座標權重：等角空間中的掃描線位置
            const coordDepth = (op.tq + op.tr) * 10000;

            // 高度權重：瓦片越高，視覺位置越靠前
            const heightTier = (op.th / 24) * 100;

            // 類別權重
            let layerScore = 0;
            if (op.type === RenderOpType.UNIT || op.type === RenderOpType.OBSTACLE) layerScore = 500;
            else if (op.type === RenderOpType.HAZARD) layerScore = 100;
            else if (op.type === RenderOpType.DECAL) layerScore = 50;

            // 針對奧義與飛行物的特殊處理 (絕對置頂)
            if (op.pIsUlt || op.z > 400) layerScore = 10000000;

            op.sortKey = coordDepth + heightTier + layerScore;
            this.sortView[i] = op;
        }

        const activeSegment = this.sortView.slice(0, this.count);
        activeSegment.sort((a, b) => a.sortKey - b.sortKey);

        for (let i = 0; i < this.count; i++) {
            this.ops[i] = activeSegment[i];
        }
    }
}

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

// 唯一幾何補償常數
const WALL_SKIRT_PX = 1.5;   // 解決下層裂縫
const TOP_SHRINK_PX = 0.2;   // 防止相鄰頂面重疊產生的閃爍
const Z_FIGHTING_LIFT = -0.1; // 極微量抬升

export const TerrainRenderer = {
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        // 物理座標捨入對齊：確保所有瓦片在物理像素邊界上對齊
        const drawX = Math.floor(x);
        const drawY = Math.floor(y);
        const visualTopY = -Math.floor(height);

        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(drawX, drawY);

        // 1. 繪製側牆 (由下而上，增加重疊補償)
        if (layout === 'FLAT') {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY - WALL_SKIRT_PX, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY - WALL_SKIRT_PX, theme.sideLight);
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY - WALL_SKIRT_PX, theme.sideDark);
        } else {
            // Pointy 佈局：繪製前方可見的兩個面
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY - WALL_SKIRT_PX, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY - WALL_SKIRT_PX, theme.sideLight);
        }

        // 2. 繪製頂部六邊形面 (Top Surface)
        ctx.translate(0, visualTopY + Z_FIGHTING_LIFT);

        // 頂面渲染：微縮幾何 (收縮 0.2px) 杜絕邊緣爭奪
        const topSize = size - TOP_SHRINK_PX;
        const topVerts = HexGeometry.getVertices(topSize, true, layout);

        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;
        ctx.beginPath();
        ctx.moveTo(topVerts[0].x, topVerts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(topVerts[i].x, topVerts[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // 強力外框 (Outline)：數學上強化塊體輪廓，視覺上遮蓋微小拼貼誤差
        ctx.strokeStyle = theme.sideDark;
        ctx.lineWidth = 0.5;
        ctx.globalAlpha = 0.3;
        ctx.stroke();

        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        }

        ctx.restore();
    },

    drawVerticalWall(ctx: CanvasRenderingContext2D, v1: {x:number, y:number}, v2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        // 矩形四點座標
        ctx.moveTo(v1.x, v1.y);
        ctx.lineTo(v2.x, v2.y);
        ctx.lineTo(v2.x, v2.y + topY);
        ctx.lineTo(v1.x, v1.y + topY);

        // 底座補強：確保牆面深入地平線
        ctx.lineTo(v1.x, v1.y + BASE_HEIGHT + 2.0); 
        ctx.closePath();
        ctx.fill();

        // 側稜線 (Bevel): 強化塊體感，防止相鄰面融為一體
        ctx.strokeStyle = 'rgba(255,255,255,0.05)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(v1.x, v1.y);
        ctx.lineTo(v1.x, v1.y + topY);
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        // 裝飾物 Y 座標必須嚴格繼承捨入後的瓦片頂面高度
        const visualY = Math.floor(baseY) - Math.floor(height) + Z_FIGHTING_LIFT;
        if (type === 'FOREST' || type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";

const OBSTACLE_Z_INDEX = 10;
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];
        const layout = engine.mapConfig.layout;

        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            const visualBaseY = py + offset;
            const visualSurfaceY = visualBaseY - h;

            if (Math.abs(offset) > 800) continue;

            // 1. 提交障礙物 (繼承 tile 座標供排序)
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.tq = q; op.tr = r; // 核心：傳入邏輯座標
                op.th = h; 
                op.tx = px; 
                op.ty = visualSurfaceY; 
                op.ttype = obstacleType;
            }

            // 2. 提交地面效果
            const hazard = engine.map.getHazardAt(q, r, engine);
            if (hazard) {
                const hOp = renderList.next();
                hOp.type = RenderOpType.HAZARD;
                hOp.tq = q; hOp.tr = r;
                hOp.th = h;
                hOp.tx = px; 
                hOp.ty = visualSurfaceY; 
                hOp.oHazard = hazard;
                hOp.time = globalTime;
            }

            // 3. 提交地形
            const zoneInfo = engine.zones.getZoneAt(q, r);
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexUtils.dist({q, r}, {q: highlightAgent.q, r: highlightAgent.r});
                if (dist <= hoveredSkill.range + bonus) { isRange = true; rangeColor = hoveredSkill.color; }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);

            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.tq = q; op.tr = r; // 核心：傳入邏輯座標
            op.tx = px; 
            op.ty = visualBaseY; 
            op.th = h;
            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { Agent } from "../../game";
import { MovementType } from "../../../types";
import { HexUtils, MapConfig } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";

export interface UnitVisualState {
    agent: Agent;
    x: number;
    y: number;
    z: number;
    terrainHeight: number;
    scale: number;
    isSilhouette: boolean;
    isSelected: boolean;
    sortY: number;
    isDead: boolean;
    isVisible: boolean;
}

export class UnitVisualProcessor {
    public static process(
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        highlightAgent: Agent | null
    ): UnitVisualState {
        const isDead = agent.hp <= 0;
        const visualX = agent.px + agent.physics.x;
        const visualY = agent.py + agent.physics.y;

        let terrainH = getTerrainHeight(agent.q, agent.r);

        // 預測插值：若正在跨越邊界，取目標格高度以防閃爍
        if (agent.isMoving && agent.path.length > 0 && agent.moveProgress > 0.5) {
            terrainH = getTerrainHeight(agent.path[0].q, agent.path[0].r);
        }

        const isSelected = (agent === highlightAgent);

        return {
            agent,
            x: visualX,
            y: visualY,
            z: agent.physics.z,
            terrainHeight: terrainH,
            scale: 1.0, 
            isSilhouette: false,
            isSelected,
            sortY: agent.py, // 使用穩定邏輯座標排序
            isDead,
            isVisible: !agent.fullyDead
        };
    }
}

import { Agent, GameEngine } from "../game";
import { RenderList, RenderOpType } from "./renderers/RenderList";
import { MapConfig } from "./utils";
import { UnitVisualProcessor } from "./systems/unit/UnitVisualProcessor";
import { UnitBodyPainter } from "./renderers/units/painters/UnitBodyPainter";
import { UnitShadowPainter } from "./renderers/units/painters/UnitShadowPainter";

export class UnitRenderSystem {
    public submitRenderables(
        renderList: RenderList,
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ) {
        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;
            const state = UnitVisualProcessor.process(agent, getTerrainHeight, mapConfig, highlightAgent);

            const op = renderList.next();
            op.type = RenderOpType.UNIT;

            // 關鍵：將單位的當前邏輯網格位置傳入
            op.tq = agent.q; 
            op.tr = agent.r;
            op.th = state.terrainHeight; 

            op.agent = agent;
            op.tx = state.x; 
            op.ty = state.y - state.terrainHeight;
            op.z = agent.physics.z; 
            op.time = globalTime;
            op.uSelected = state.isSelected;
        });
    }

    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        mapConfig: MapConfig
    ) {
        const state = UnitVisualProcessor.process(agent, getTerrainHeight, mapConfig, null);
        const visualGroundY = state.y - state.terrainHeight;
        this.drawAssembly(ctx, agent, state.x, visualGroundY, agent.physics.z, globalTime, false, true);
    }

    public drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        localZ: number,
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        ctx.save();
        ctx.translate(drawX, drawY); 
        if (!isSilhouette && agent.hp > 0) {
            UnitShadowPainter.draw(ctx, agent, 0, 0, localZ, globalTime, isSilhouette);
        }
        UnitBodyPainter.draw(ctx, agent, 0, 0, localZ, globalTime, isSilhouette, isSelected, 1.0);
        ctx.restore(); 
    }
}

