    dColor: string = ''; dScale: number = 1; dLife: number = 0;
    time: number = 0;

    public clear() {
        this.type = RenderOpType.TERRAIN;
        this.sortKey = 0;
        this.y = 0; this.z = 0;
        this.tx = 0; this.ty = 0; this.th = 0;
        this.tq = 0; this.tr = 0;
        this.agent = null;
        this.particle = null;
        this.proj = null;
        this.pIsUlt = false; 
        this.oRange = false;
        this.oHover = false;
        this.oStatus = undefined;
        this.oHazard = undefined;
        this.oDanger = undefined;
        this.uSelected = false;
        this.uSilhouette = false;
        this.vChaos = false;
        this.ttheme = null;
        this.pTrail = [];
    }
}

export class RenderList {
    public ops: RenderOp[] = [];
    public count: number = 0;
    private sortView: RenderOp[] = [];
    private capacity: number = 8000;

    constructor() {
        for(let i=0; i<this.capacity; i++) {
            const op = new RenderOp();
            this.ops.push(op);
            this.sortView.push(op); 
        }
    }

    public reset() {
        this.count = 0;
    }

    public next(): RenderOp {
        if (this.count >= this.ops.length) {
            for(let i=0; i<1000; i++) {
                const op = new RenderOp();
                this.ops.push(op);
                this.sortView.push(op);
            }
        }
        const op = this.ops[this.count++];
        op.clear(); 
        return op;
    }

    public sort() {
        if (this.count <= 1) return;
        for (let i = 0; i < this.count; i++) {
            const op = this.ops[i];

            /**
             * 唯一數學排序規範 v17.0 (Topological Depth Sort)
             * 
             * 1. 核心排序 (Base Depth): 使用 op.y (Screen Base Y) 進行排序。
             *    這符合畫家演算法：螢幕上方 (Low Y) 的物體是背景，應先繪製。
             * 
             * 2. 圖層優先級 (Layer): 在相同的 Y 軸位置，依序繪製 地形 -> 裝飾 -> 單位 -> 特效。
             * 
             * 3. 嚴禁使用高度 (th) 參與排序：
             *    地形的高度是幾何屬性，不影響其在地基平面上的前後關係。
             */

            // Layer Constants (Low to High)
            // TERRAIN (0) < DECAL (1) < HAZARD (2) < OBSTACLE (3) < UNIT (4) < PROJECTILE (5) < VFX (6)

            let layerScore = 0;
            switch(op.type) {
                case RenderOpType.TERRAIN: layerScore = 0; break;
                case RenderOpType.DECAL: layerScore = 10; break;
                case RenderOpType.HAZARD: layerScore = 20; break;
                case RenderOpType.OBSTACLE: layerScore = 30; break;
                case RenderOpType.UNIT: layerScore = 40; break;
                case RenderOpType.PROJECTILE: layerScore = 50; break;
                case RenderOpType.VFX: layerScore = 60; break;
            }

            // Special Case: Ultimates or High-Z Objects always on top layer
            if (op.pIsUlt || op.z > 600) layerScore += 1000;

            // Sort Key Construction
            // Multiplier 1000 ensures Y precision dominates Layer
            // Offset 20000 ensures positive values if Y is negative (rare but safe)
            const yScore = Math.floor(op.y + 20000) * 10000;

            op.sortKey = yScore + layerScore + Math.floor(op.z);
            this.sortView[i] = op;
        }

        const activeSegment = this.sortView.slice(0, this.count);
        activeSegment.sort((a, b) => a.sortKey - b.sortKey);

        for (let i = 0; i < this.count; i++) {
            this.ops[i] = activeSegment[i];
        }
    }
}

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

// 幾何常數
const PEDESTAL_DEPTH = 300; // 基座向下延伸深度 (Curtain)，解決高低差穿幫
const EXPANSION_BIAS = 0.6; // 數學膨脹量 (px)，解決 T-Junction 縫隙

export const TerrainRenderer = {
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        // 物理座標取整，避免模糊
        const drawX = Math.floor(x);
        const drawY = Math.floor(y);

        // 視覺頂面 Y 軸 (相對於 drawY)
        const visualTopY = -Math.floor(height);

        // 膨脹幾何半徑 (Anti-gap)
        const r = size + EXPANSION_BIAS;
        const vertices = HexGeometry.getVertices(r, true, layout); 

        ctx.save();
        ctx.translate(drawX, drawY);

        // 1. 繪製基座與側牆 (Pedestal Curtain)
        // 側牆從 visualTopY (頂端) 一路延伸至 PEDESTAL_DEPTH (深淵)
        // 這確保了無論前方瓦片多低，都不會看到此瓦片的底部懸空

        const drawFace = (idx1: number, idx2: number, color: string) => {
            const v1 = vertices[idx1];
            const v2 = vertices[idx2];

            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY); // Top-Left
            ctx.lineTo(v2.x, v2.y + visualTopY); // Top-Right
            ctx.lineTo(v2.x, v2.y + PEDESTAL_DEPTH); // Bottom-Right (Deep)
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH); // Bottom-Left (Deep)
            ctx.closePath();
            ctx.fill();

            // 側邊高光稜線 (僅上半部，避免深處雜訊)
            ctx.strokeStyle = 'rgba(255,255,255,0.05)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v1.x, v1.y + visualTopY + BLOCK_HEIGHT * 2);
            ctx.stroke();
        };

        if (layout === 'FLAT') {
            // Flat Top 模式的可見面：右下、下、左下
            drawFace(1, 0, theme.sideDark);  // Right-Bottom
            drawFace(2, 1, theme.sideLight); // Bottom
            drawFace(3, 2, theme.sideDark);  // Left-Bottom
        } else {
            // Pointy Top 模式的可見面：右、左
            // 依據 HexGeometry 頂點順序：0(E), 1(SE), 2(SW), 3(W)...
            // 前向面通常是 1->0 (右側) 和 2->1 (左側) ??? 
            // 需對照 HexGeometry.getVertices 的順序。
            // Pointy: 0 is Right, 1 is BottomRight, 2 is BottomLeft...
            // 可見面是 1-0 (SE Face) ? No. 
            // 讓我們先畫最安全的兩個前向面

            // Side Right (Vertices 1 -> 0)
            drawFace(1, 0, theme.sideDark);

            // Side Left (Vertices 2 -> 1)
            drawFace(2, 1, theme.sideLight);
        }

        // 2. 繪製頂部 (Top Cap)
        ctx.translate(0, visualTopY);

        const topGrad = ctx.createLinearGradient(-r, -r, r, r);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;
        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // 頂部描邊 (Rim) - 強化輪廓
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.0;
        ctx.globalAlpha = 0.5;
        ctx.stroke();

        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        }

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        // 裝飾物跟隨頂面高度
        const visualY = Math.floor(baseY) - Math.floor(height);
        if (type === 'FOREST' || type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

export class MapGenerator {
    public static randomize(system: MapSystem, engine: GameEngine) {
        const layout = engine.mapConfig.layout;
        let cols, rows;

        if (layout === 'FLAT') {
            cols = 8 + Math.floor(Math.random() * 2); 
            rows = 10 + Math.floor(Math.random() * 2); 
        } else {
            cols = 7 + Math.floor(Math.random() * 2); 
            rows = 12 + Math.floor(Math.random() * 2); 
        }

        engine.mapConfig.w = cols; 
        engine.mapConfig.h = rows; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();
        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        // Fix: Determine center in Offset space first, then convert to Axial
        // This ensures the heightmap "bowl" is centered visually on the rectangle
        const centerCol = Math.floor((W - 1) / 2);
        const centerRow = Math.floor((H - 1) / 2);
        const centerHex = HexUtils.offsetToAxial(centerCol, centerRow, engine.mapConfig);

        const noisePhaseA = Math.random() * 1000;
        const noisePhaseB = Math.random() * 1000;

        // Fix: Rhombus Trap -> Rectangle Loop
        // Iterate over visual Columns and Rows (Offset Coordinates)
        for (let row = 0; row < H; row++) {
            for (let col = 0; col < W; col++) {
                // Convert to Axial for internal storage
                const hex = HexUtils.offsetToAxial(col, row, engine.mapConfig);
                const q = hex.q;
                const r = hex.r;

                const k = HexUtils.key({q, r});
                system.registerTile(q, r);

                const dist = HexUtils.dist({q, r}, centerHex);

                // 核心數學：階梯狀高度函數 (Stepped Height Field)
                let rawVal = (Math.sin((q + noisePhaseA) * 0.4) + Math.cos((r + noisePhaseB) * 0.4)) * 2.0;
                rawVal += (dist * 0.5); // 基礎碗狀趨勢

                // 離散化為 Tier 層級
                let tier = Math.round(rawVal);
                tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));

                // 確保中心區域平坦
                if (dist < 1.5) tier = 0;

                tiers.set(k, tier);
            }
        }

        // 高度場平滑
        const smoothedTiers = new Map<string, number>();
        tiers.forEach((tier, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let minN = tier;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tiers.has(nk)) minN = Math.min(minN, tiers.get(nk)! + 1);
            });
            smoothedTiers.set(key, minN);
        });

        smoothedTiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine, W, H);
        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine, W: number, H: number) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        // Approximate center for obstacle avoidance
        const centerCol = Math.floor(W / 2);
        const centerRow = Math.floor(H / 2);
        const centerHex = HexUtils.offsetToAxial(centerCol, centerRow, engine.mapConfig);

        const keys = Array.from(system.getMapKeys());

        keys.forEach((key) => {
            const [q, r] = key.split(',').map(Number);
            const dist = HexUtils.dist({q, r}, centerHex);

            if (dist < 2.5) return; 
            if (engine.getAgentAt(q, r)) return;

            const noise = Math.sin(q * 0.8) * Math.cos(r * 0.8);
            if (noise > 0.4 && Math.random() < 0.3) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }
}

import { Hex, Point, Cube, HexLayout } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

export { Cube };

const SQRT3 = Math.sqrt(3);

export const HexMath = {

    directions: [
        { q: 1, r: 0 }, { q: 1, r: -1 }, { q: 0, r: -1 },
        { q: -1, r: 0 }, { q: -1, r: 1 }, { q: 0, r: 1 }
    ],

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    /**
     * Standard Hex to Pixel Mapping (SSOT)
     * Supports both Flat-Top and Pointy-Top orientations.
     * Applies ISO_SCALE_Y to Y-axis for 2.5D projection.
     */
    hexToPixel(q: number, r: number, offsetX: number, offsetY: number, layout: HexLayout): Point {
        let x = 0;
        let y = 0;

        if (layout === 'FLAT') {
            // Flat Top
            // Width = 2 * size
            // Height = sqrt(3) * size
            // Horizontal spacing = 3/2 * size
            x = HEX_SIZE * (3/2 * q);
            y = HEX_SIZE * (SQRT3/2 * q + SQRT3 * r);
        } else {
            // Pointy Top
            // Width = sqrt(3) * size
            // Height = 2 * size
            // Horizontal spacing = sqrt(3) * size
            x = HEX_SIZE * (SQRT3 * q + SQRT3/2 * r);
            y = HEX_SIZE * (3/2 * r);
        }

        // Apply Isometric Compression (The "View" Transform)
        y = y * ISO_SCALE_Y;

        return {
            x: x + offsetX,
            y: y + offsetY
        };
    },

    /**
     * Inverse mapping for Picking
     */
    pixelToHex(x: number, y: number, offsetX: number, offsetY: number, layout: HexLayout): Hex {
        const dx = x - offsetX;
        const dy = (y - offsetY) / ISO_SCALE_Y; // Un-squash Y

        let q = 0;
        let r = 0;

        if (layout === 'FLAT') {
            q = (2/3 * dx) / HEX_SIZE;
            r = (-1/3 * dx + SQRT3/3 * dy) / HEX_SIZE;
        } else {
            q = (SQRT3/3 * dx - 1/3 * dy) / HEX_SIZE;
            r = (2/3 * dy) / HEX_SIZE;
        }

        return this.cubeToAxial(this.cubeRound(this.axialToCube({q, r})));
    },

    distance(a: Hex, b: Hex): number {
        const ac = this.axialToCube(a);
        const bc = this.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = this.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(this.cubeToAxial(this.cubeRound(cubeLerp)));
        }
        return results;
    },

    neighbors(h: Hex): Hex[] {
        return this.directions.map(d => ({ q: h.q + d.q, r: h.r + d.r }));
    }
};

import { BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

// 幾何常數
const PEDESTAL_DEPTH = 300; // 基座向下延伸深度 (Curtain)，解決高低差穿幫
const EXPANSION_BIAS = 0.6; // 數學膨脹量 (px)，解決 T-Junction 縫隙

export const TerrainRenderer = {
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        // 物理座標取整，避免模糊
        const drawX = Math.floor(x);
        const drawY = Math.floor(y);

        // 視覺頂面 Y 軸 (相對於 drawY)
        const visualTopY = -Math.floor(height);

        // 膨脹幾何半徑 (Anti-gap)
        const r = size + EXPANSION_BIAS;
        const vertices = HexGeometry.getVertices(r, true, layout); 

        ctx.save();
        // Strict Translation: Move context to the exact center of the hex calculated by HexMath
        ctx.translate(drawX, drawY);

        // 1. 繪製基座與側牆 (Pedestal Curtain)
        const drawFace = (idx1: number, idx2: number, color: string) => {
            const v1 = vertices[idx1];
            const v2 = vertices[idx2];

            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY); // Top-Left
            ctx.lineTo(v2.x, v2.y + visualTopY); // Top-Right
            ctx.lineTo(v2.x, v2.y + PEDESTAL_DEPTH); // Bottom-Right (Deep)
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH); // Bottom-Left (Deep)
            ctx.closePath();
            ctx.fill();

            // 側邊高光稜線
            ctx.strokeStyle = 'rgba(255,255,255,0.05)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v1.x, v1.y + visualTopY + BLOCK_HEIGHT * 2);
            ctx.stroke();
        };

        if (layout === 'FLAT') {
            // Flat Top 模式的可見面：右下、下、左下 (Indices 1, 2, 3)
            drawFace(1, 0, theme.sideDark);  // Right-Bottom
            drawFace(2, 1, theme.sideLight); // Bottom
            drawFace(3, 2, theme.sideDark);  // Left-Bottom
        } else {
            // Pointy Top 模式的可見面：右、左 (Indices 0->1, 1->2 ?)
            // HexGeometry standard: 0=0deg, 1=60deg... 
            // In Iso, Pointy top has vertices at 30, 90, 150...
            // Standard Pointy vertices start at 30deg (PI/6).
            // Indices: 0(30, SE), 1(90, S), 2(150, SW)...
            // So visible faces are 0->1 (Right) and 1->2 (Left)
            drawFace(1, 0, theme.sideDark);
            drawFace(2, 1, theme.sideLight);
        }

        // 2. 繪製頂部 (Top Cap)
        ctx.translate(0, visualTopY);

        const topGrad = ctx.createLinearGradient(-r, -r, r, r);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;
        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // 頂部描邊 (Rim) - 強化輪廓
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.0;
        ctx.globalAlpha = 0.5;
        ctx.stroke();

        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        }

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = Math.floor(baseY) - Math.floor(height);
        if (type === 'FOREST' || type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { RenderOp } from "./RenderList";
import { AssetManager } from "../assets";

/**
 * 飛行物視覺呈現器 v14.1 - Crash Safe
 */
export const ProjectileDrawer = {
    draw(ctx: CanvasRenderingContext2D, op: RenderOp, globalTime: number) {
        const { pVisX: x, pVisY: y, pColor: color, pAngle: angle, pTrail: trail } = op;

        // Basic safety check for main coordinates
        if (!Number.isFinite(x) || !Number.isFinite(y)) return;

        // 1. 渲染能量尾跡 (Analytic Gradient Trail)
        if (trail && trail.length > 1) {
            const endP = trail[trail.length-1];

            // Check trail endpoint validity for gradient creation
            if (Number.isFinite(endP.x) && Number.isFinite(endP.y)) {
                ctx.save();
                ctx.globalCompositeOperation = 'screen';
                ctx.beginPath();
                ctx.moveTo(x, y);

                for (let i = 0; i < trail.length; i++) {
                    ctx.lineTo(trail[i].x, trail[i].y);
                }

                try {
                    const trailGrad = ctx.createLinearGradient(x, y, endP.x, endP.y);
                    trailGrad.addColorStop(0, color);
                    trailGrad.addColorStop(1, 'transparent');

                    ctx.strokeStyle = trailGrad;
                    ctx.lineWidth = op.pIsUlt ? 8 : 3;
                    ctx.globalAlpha = 0.6;
                    ctx.lineCap = 'round';
                    ctx.stroke();
                } catch (e) {
                    // Fallback if gradient fails (e.g. identical points)
                    ctx.strokeStyle = color;
                    ctx.stroke();
                }
                ctx.restore();
            }
        }

        // 2. 主體精靈渲染
        ctx.save();
        ctx.translate(x, y);

        // 運動模糊模擬：根據速度向量進行視覺拉伸 (SSOT: 此處假設速度影響拉伸)
        const stretch = op.pIsUlt ? 1.5 : 1.15;
        if (op.pSpin !== 0) {
            ctx.rotate(op.pSpin);
        } else {
            ctx.rotate(angle);
            ctx.scale(stretch, 1.0 / stretch); // 體積守恆拉伸
        }

        const img = AssetManager.getProjectile(op.pSkillVis, color);
        if (img) {
            const scale = op.pIsUlt ? 1.8 : 1.2;

            // 底層：基礎色
            ctx.globalAlpha = 1.0;
            ctx.drawImage(img, -32 * scale, -32 * scale, 64 * scale, 64 * scale);

            // 頂層：動態發光 (Additive Pulse)
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.4 + Math.sin(globalTime * 20) * 0.2;
            ctx.drawImage(img, -36 * scale, -36 * scale, 72 * scale, 72 * scale);
        }

        ctx.restore();

        // 3. 亮點補償 (奧義專用)
        if (op.pIsUlt) {
            ctx.save();
            ctx.translate(x, y);
            ctx.globalCompositeOperation = 'screen';
            const flare = ctx.createRadialGradient(0,0,0, 0,0, 40);
            flare.addColorStop(0, '#fff');
            flare.addColorStop(0.3, color);
            flare.addColorStop(1, 'transparent');
            ctx.fillStyle = flare;
            ctx.beginPath(); ctx.arc(0,0, 40, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }
    }
};

import { BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

// 幾何常數
const PEDESTAL_DEPTH = 300; // 基座向下延伸深度 (Curtain)，解決高低差穿幫
const EXPANSION_BIAS = 0.6; // 數學膨脹量 (px)，解決 T-Junction 縫隙

export const TerrainRenderer = {
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        // 物理座標取整，避免模糊
        const drawX = Math.floor(x);
        const drawY = Math.floor(y);

        // 視覺頂面 Y 軸 (相對於 drawY)
        const visualTopY = -Math.floor(height);

        // 膨脹幾何半徑 (Anti-gap)
        const r = size + EXPANSION_BIAS;
        const vertices = HexGeometry.getVertices(r, true, layout); 

        ctx.save();
        // Strict Translation: Move context to the exact center of the hex calculated by HexMath
        ctx.translate(drawX, drawY);

        // 1. 繪製基座與側牆 (Pedestal Curtain)
        const drawFace = (idx1: number, idx2: number, color: string) => {
            const v1 = vertices[idx1];
            const v2 = vertices[idx2];

            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY); // Top-Left
            ctx.lineTo(v2.x, v2.y + visualTopY); // Top-Right
            ctx.lineTo(v2.x, v2.y + PEDESTAL_DEPTH); // Bottom-Right (Deep)
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH); // Bottom-Left (Deep)
            ctx.closePath();
            ctx.fill();

            // 側邊高光稜線
            ctx.strokeStyle = 'rgba(255,255,255,0.05)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v1.x, v1.y + visualTopY + BLOCK_HEIGHT * 2);
            ctx.stroke();
        };

        if (layout === 'FLAT') {
            // Flat Top 模式的可見面：右下、下、左下 (Indices 1, 2, 3)
            drawFace(1, 0, theme.sideDark);  // Right-Bottom
            drawFace(2, 1, theme.sideLight); // Bottom
            drawFace(3, 2, theme.sideDark);  // Left-Bottom
        } else {
            // Pointy Top 模式的可見面：右、左 (Indices 0->1, 1->2 ?)
            // HexGeometry standard: 0=0deg, 1=60deg... 
            // In Iso, Pointy top has vertices at 30, 90, 150...
            // Standard Pointy vertices start at 30deg (PI/6).
            // Indices: 0(30, SE), 1(90, S), 2(150, SW)...
            // So visible faces are 0->1 (Right) and 1->2 (Left)
            drawFace(1, 0, theme.sideDark);
            drawFace(2, 1, theme.sideLight);
        }

        // 2. 繪製頂部 (Top Cap)
        ctx.translate(0, visualTopY);

        // Safety check for gradient radius to prevent crashes
        if (Number.isFinite(r) && r > 0) {
            const topGrad = ctx.createLinearGradient(-r, -r, r, r);
            topGrad.addColorStop(0, theme.rim); 
            topGrad.addColorStop(0.5, theme.top);
            topGrad.addColorStop(1, theme.sideDark); 
            ctx.fillStyle = topGrad;
        } else {
            ctx.fillStyle = theme.top;
        }

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // 頂部描邊 (Rim) - 強化輪廓
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.0;
        ctx.globalAlpha = 0.5;
        ctx.stroke();

        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        }

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = Math.floor(baseY) - Math.floor(height);
        if (type === 'FOREST' || type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { Agent } from "../../game";
import { Team } from "../../../types";

const BAR_WIDTH = 44;
const BAR_HEIGHT = 6;
const BAR_PADDING = 3;

export const BarPainter = {

    drawUnitBars(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, isSelected: boolean) {
        if (!Number.isFinite(x) || !Number.isFinite(y)) return;

        const hasMp = agent.maxMp > 0;

        const contentW = BAR_WIDTH;
        const hpHeight = BAR_HEIGHT;
        const mpHeight = hasMp ? 3 : 0;
        const gap = hasMp ? 2 : 0;

        const contentH = hpHeight + gap + mpHeight;
        const totalW = contentW + BAR_PADDING * 2;
        const totalH = contentH + BAR_PADDING * 2;

        const startX = x - totalW / 2;
        const startY = y - 5; 

        // Container
        ctx.save();
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(startX, startY, totalW, totalH, 6);
        else ctx.rect(startX, startY, totalW, totalH);

        // Dark Glass BG
        ctx.fillStyle = 'rgba(2, 6, 23, 0.7)'; 
        ctx.fill();

        // Team-colored Border Highlight
        const teamBorder = agent.team === Team.BLUE ? '#3b82f6' : '#ef4444';
        ctx.lineWidth = 1;
        ctx.strokeStyle = isSelected ? teamBorder : 'rgba(255, 255, 255, 0.15)';
        ctx.stroke();

        if (isSelected) {
            ctx.shadowColor = teamBorder;
            ctx.shadowBlur = 10;
            ctx.stroke();
            ctx.shadowBlur = 0;
        }
        ctx.restore();

        const barX = startX + BAR_PADDING;
        const barY = startY + BAR_PADDING;

        // HP Bar - Faction Colored
        const hpPct = Math.max(0, agent.hp / (agent.maxHp || 1));

        // Calculate Shield Pct (Relative to Max HP)
        const shieldPct = Math.max(0, agent.shield / (agent.maxHp || 1));

        let hpTop, hpBot, hpGlow;

        if (agent.team === Team.BLUE) {
            // IMPERIAL CYAN/BLUE
            hpTop = '#22d3ee';
            hpBot = '#0284c7';
            hpGlow = 'rgba(6, 182, 212, 0.5)';
        } else {
            // COVENANT RED/ORANGE
            hpTop = '#f87171';
            hpBot = '#dc2626';
            hpGlow = 'rgba(220, 38, 38, 0.5)';
        }

        // Draw Base HP
        this.drawFluidBar(ctx, barX, barY, contentW, hpHeight, hpPct, hpTop, hpBot, hpGlow);

        // Draw Shield Overlay
        if (shieldPct > 0) {
            // Shield starts where HP ends
            const shieldStartX = barX + (contentW * hpPct);
            // Cap visual shield width so it doesn't overflow container absurdly (max 100% of bar width total)
            const remainingSpace = 1.0 - hpPct;
            const visualShieldPct = Math.min(shieldPct, remainingSpace + 0.2); // Allow slight overflow visual
            const shieldW = contentW * visualShieldPct;

            // Shield Colors (White/Grey/Blue-ish)
            const shieldTop = '#e2e8f0';
            const shieldBot = '#94a3b8';

            ctx.save();
            ctx.beginPath();
            if (ctx.roundRect) ctx.roundRect(shieldStartX, barY, shieldW, hpHeight, 0);
            else ctx.rect(shieldStartX, barY, shieldW, hpHeight);

            if (Number.isFinite(shieldStartX) && Number.isFinite(barY) && Number.isFinite(hpHeight)) {
                const grad = ctx.createLinearGradient(shieldStartX, barY, shieldStartX, barY + hpHeight);
                grad.addColorStop(0, shieldTop);
                grad.addColorStop(1, shieldBot);
                ctx.fillStyle = grad;
            } else {
                ctx.fillStyle = shieldTop;
            }
            ctx.fill();

            // Shield Border to separate from HP
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 1;
            ctx.stroke();

            // Over-shield indicator (if shield exceeds max HP visual)
            if (hpPct + shieldPct > 1.0) {
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 1.5;
                ctx.strokeRect(barX, barY, contentW, hpHeight);
            }
            ctx.restore();
        }

        // MP Bar - Always Blue/Purple
        if (hasMp) {
            const mpPct = Math.max(0, agent.mp / (agent.maxMp || 1));
            const mpY = barY + hpHeight + gap;
            this.drawFluidBar(ctx, barX, mpY, contentW, mpHeight, mpPct, '#a78bfa', '#7c3aed', 'rgba(139, 92, 246, 0.4)');
        }
    },

    drawFluidBar(ctx: CanvasRenderingContext2D, bx: number, by: number, bw: number, bh: number, pct: number, colTop: string, colBot: string, glow: string) {
        if (pct <= 0.01) return;
        if (!Number.isFinite(bx) || !Number.isFinite(by) || !Number.isFinite(bh)) return;

        const fillW = Math.max(bh, bw * pct); 

        ctx.save();
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh, bh/2);
        else ctx.rect(bx, by, fillW, bh);

        const grad = ctx.createLinearGradient(bx, by, bx, by + bh);
        grad.addColorStop(0, colTop);
        grad.addColorStop(1, colBot);
        ctx.fillStyle = grad;

        ctx.shadowColor = glow;
        ctx.shadowBlur = 5;
        ctx.fill();
        ctx.shadowBlur = 0;

        // Gloss
        ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh * 0.4, bh/2);
        else ctx.rect(bx, by, fillW, bh * 0.4);
        ctx.fill();

        ctx.restore();
    }
};

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../utils/HexGeometry";
import { VFXFactory } from "../VFXFactory";
import { HexLayout } from "../../../types";

export const VolumePainter = {

    draw3DPrism(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number,
        style: 'SOLID' | 'GRADIENT_FADE' | 'HATCHED_WARNING',
        layout: HexLayout = 'FLAT'
    ) {
        if (!Number.isFinite(height) || height <= 0) return;

        const topY = y - height;

        ctx.save();
        ctx.translate(x, y); 

        const verts = HexGeometry.getVertices(radius, true, layout);
        const indices = [5, 0, 1]; 

        for (const i of indices) {
            const j = (i + 1) % 6;
            const v1 = verts[i];
            const v2 = verts[j];

            const grad = ctx.createLinearGradient(0, -height, 0, 0);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent'); 

            ctx.fillStyle = grad;
            ctx.globalAlpha = opacity * 0.5; 

            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y);           
            ctx.lineTo(v2.x, v2.y);           
            ctx.lineTo(v2.x, v2.y - height);  
            ctx.lineTo(v1.x, v1.y - height);  
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y);
            ctx.lineTo(v1.x, v1.y - height);
            ctx.stroke();

            if (i === 1) { 
                 ctx.beginPath(); ctx.moveTo(v2.x, v2.y); ctx.lineTo(v2.x, v2.y - height); ctx.stroke();
            }
        }

        ctx.translate(0, -height);
        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.3;
        HexGeometry.traceHex(ctx, 0, 0, radius, true, layout);
        ctx.fill();

        ctx.strokeStyle = color;
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 1.0;
        HexGeometry.traceHex(ctx, 0, 0, radius, true, layout);
        ctx.stroke();

        ctx.restore();
    },

    drawVolumetricHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        const texture = VFXFactory.getTexture('ATMOSPHERE', color);
        const size = radius * 2.8; 

        ctx.save();
        ctx.translate(x, y);
        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'screen';
        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawHexRipple(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number,
        width: number,
        layout: HexLayout = 'FLAT'
    ) {
        ctx.save();
        ctx.globalAlpha = opacity;
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.lineCap = 'round';

        ctx.shadowColor = color;
        ctx.shadowBlur = width * 1.5;

        HexGeometry.traceHex(ctx, x, y, radius, true, layout);
        ctx.stroke();

        ctx.lineWidth = width * 0.2;
        ctx.strokeStyle = '#ffffff';
        ctx.shadowBlur = 0;
        ctx.stroke();

        ctx.restore();
    },

    drawExtrusion(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number,
        layout: HexLayout = 'FLAT'
    ) {
        if (!Number.isFinite(height)) return;

        const verts = HexGeometry.getVertices(radius, true, layout);
        const indices = [5, 0, 1];

        ctx.save();
        ctx.translate(x, y);
        ctx.globalAlpha = opacity;

        for (const i of indices) {
            const j = (i + 1) % 6;
            const v1 = verts[i];
            const v2 = verts[j];

            const grad = ctx.createLinearGradient(0, -height, 0, 0);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y - height);
            ctx.lineTo(v2.x, v2.y - height);
            ctx.lineTo(v2.x, v2.y);
            ctx.lineTo(v1.x, v1.y);
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.stroke();
        }

        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.6;
        HexGeometry.traceHex(ctx, 0, -height, radius, true, layout);
        ctx.fill();

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        ctx.stroke();

        ctx.restore();
    }
};

import { Hex, Point, Cube, HexLayout } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

export { Cube };

const SQRT3 = Math.sqrt(3);

export const HexMath = {

    directions: [
        { q: 1, r: 0 }, { q: 1, r: -1 }, { q: 0, r: -1 },
        { q: -1, r: 0 }, { q: -1, r: 1 }, { q: 0, r: 1 }
    ],

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    /**
     * Standard Hex to Pixel Mapping (SSOT)
     */
    hexToPixel(q: number, r: number, offsetX: number, offsetY: number, layout: HexLayout): Point {
        let x = 0;
        let y = 0;

        if (layout === 'FLAT') {
            x = HEX_SIZE * (3/2 * q);
            y = HEX_SIZE * (SQRT3/2 * q + SQRT3 * r);
        } else {
            x = HEX_SIZE * (SQRT3 * q + SQRT3/2 * r);
            y = HEX_SIZE * (3/2 * r);
        }

        y = y * ISO_SCALE_Y;

        return {
            x: x + offsetX,
            y: y + offsetY
        };
    },

    /**
     * Inverse mapping for Picking
     */
    pixelToHex(x: number, y: number, offsetX: number, offsetY: number, layout: HexLayout): Hex {
        const dx = x - offsetX;
        const dy = (y - offsetY) / ISO_SCALE_Y;

        let q = 0;
        let r = 0;

        if (layout === 'FLAT') {
            q = (2/3 * dx) / HEX_SIZE;
            r = (-1/3 * dx + SQRT3/3 * dy) / HEX_SIZE;
        } else {
            q = (SQRT3/3 * dx - 1/3 * dy) / HEX_SIZE;
            r = (2/3 * dy) / HEX_SIZE;
        }

        return this.cubeToAxial(this.cubeRound(this.axialToCube({q, r})));
    },

    distance(a: Hex, b: Hex): number {
        const ac = this.axialToCube(a);
        const bc = this.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = this.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(this.cubeToAxial(this.cubeRound(cubeLerp)));
        }
        return results;
    },

    neighbors(h: Hex): Hex[] {
        return this.directions.map(d => ({ q: h.q + d.q, r: h.r + d.r }));
    }
};

import { HEX_SIZE, ISO_SCALE_Y } from "../constants";
import { Hex, Point, HexLayout } from "../types";
import { HexMath } from "./math/HexMath"; // Strict relative path

export interface MapConfig {
    w: number;
    h: number;
    offsetX: number;
    offsetY: number;
    layout: HexLayout;
}
const Q_BIT_SHIFT = 16;
const Q_OFFSET = 128;
const R_OFFSET = 128;
export const NEIGHBOR_HASH_OFFSETS = [
    (1 << Q_BIT_SHIFT),
    (1 << Q_BIT_SHIFT) - 1,
    -1,
    -(1 << Q_BIT_SHIFT),
    -(1 << Q_BIT_SHIFT) + 1,
    1
];
export function getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
    if (phase === 'IDLE') return 0;
    const cx = mapConfig.offsetX;
    const cy = mapConfig.offsetY;
    const dist = Math.sqrt((x - cx)**2 + (y - cy)**2);
    const maxDist = 1000;
    const d = Math.min(1, dist / maxDist);
    const BASE_OFFSET = 1500;
    if (phase === 'OUT') {
        const startT = d * 0.3;
        if (t < startT) return 0;
        let localT = (t - startT) * 1.8;
        localT = Math.max(0, Math.min(1, localT));
        const s = 0.5;
        const eased = localT * localT * ((s + 1) * localT - s);
        return eased * BASE_OFFSET;
    } else if (phase === 'IN') {
        const startT = d * 0.2;
        if (t < startT) return BASE_OFFSET;
        let localT = (t - startT) * 1.5;
        localT = Math.max(0, Math.min(1, localT));
        const eased = 1 - Math.pow(1 - localT, 4);
        return (1 - eased) * BASE_OFFSET;
    }
    return 0;
}
export const HexUtils = {
    offsetToAxial: (col: number, row: number, config: MapConfig): Hex => {
        if (config.layout === 'FLAT') {
            const q = col;
            const r = row - (col - (col & 1)) / 2;
            return { q, r };
        } else {
            const q = col - (row - (row & 1)) / 2;
            const r = row;
            return { q, r };
        }
    },
    toPx: (q: number, r: number, config: MapConfig): Point => {
        return HexMath.hexToPixel(q, r, config.offsetX, config.offsetY, config.layout);
    },
    fromPx: (x: number, y: number, config: MapConfig): Hex => {
        const frac = HexMath.pixelToHex(x, y, config.offsetX, config.offsetY, config.layout);
        return HexMath.cubeToAxial(HexMath.cubeRound(HexMath.axialToCube(frac)));
    },
    round: (q: number, r: number): Hex => {
        const c = HexMath.cubeRound({x: q, z: r, y: -q-r});
        return { q: c.x, r: c.z };
    },
    dist: (a: Hex, b: Hex): number => {
        return HexMath.distance(a, b);
    },
    lerp: (a: number, b: number, t: number): number => a + (b - a) * t,
    key: (h: Hex): string => `${Math.round(h.q)},${Math.round(h.r)}`,
    hash: (q: number, r: number): number => {
        return (Math.round(q) + Q_OFFSET) << Q_BIT_SHIFT | (Math.round(r) + R_OFFSET);
    },
    unhash: (h: number): Hex => {
        const r = (h & 0xFFFF) - R_OFFSET;
        const q = (h >> Q_BIT_SHIFT) - Q_OFFSET;
        return { q, r };
    },
    neighbors: (h: Hex): Hex[] => {
        return HexMath.neighbors(h);
    },
    range: (center: Hex, n: number): Hex[] => {
        return HexMath.range(center, n);
    },
    line: (a: Hex, b: Hex): Hex[] => {
        return HexMath.line(a, b);
    }
};
export const Vector = {
    sub: (a: Point, b: Point): Point => ({ x: a.x - b.x, y: a.y - b.y }),
    add: (a: Point, b: Point): Point => ({ x: a.x + b.x, y: a.y + b.y }),
    mult: (a: Point, s: number): Point => ({ x: a.x * s, y: a.y * s }),
    lerp: (a: Point, b: Point, t: number): Point => ({
        x: a.x + (b.x - a.x) * t,
        y: a.y + (b.y - a.y) * t
    }),
    mag: (a: Point): number => Math.sqrt(a.x * a.x + a.y * a.y),
    normalize: (a: Point): Point => {
        const m = Vector.mag(a);
        return m === 0 ? { x: 0, y: 0 } : { x: a.x / m, y: a.y / m };
    },
    dist: (a: Point, b: Point): number => Vector.mag(Vector.sub(a, b))
};

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

export class MapGenerator {
    public static randomize(system: MapSystem, engine: GameEngine) {
        const layout = engine.mapConfig.layout;
        let cols, rows;

        if (layout === 'FLAT') {
            cols = 8 + Math.floor(Math.random() * 2); 
            rows = 10 + Math.floor(Math.random() * 2); 
        } else {
            cols = 7 + Math.floor(Math.random() * 2); 
            rows = 12 + Math.floor(Math.random() * 2); 
        }

        engine.mapConfig.w = cols; 
        engine.mapConfig.h = rows; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();
        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        const centerCol = Math.floor((W - 1) / 2);
        const centerRow = Math.floor((H - 1) / 2);
        const centerHex = HexUtils.offsetToAxial(centerCol, centerRow, engine.mapConfig);

        const noisePhaseA = Math.random() * 1000;
        const noisePhaseB = Math.random() * 1000;

        for (let row = 0; row < H; row++) {
            for (let col = 0; col < W; col++) {
                const hex = HexUtils.offsetToAxial(col, row, engine.mapConfig);
                const q = hex.q;
                const r = hex.r;

                const k = HexUtils.key({q, r});
                system.registerTile(q, r);

                const dist = HexUtils.dist({q, r}, centerHex);

                let rawVal = (Math.sin((q + noisePhaseA) * 0.4) + Math.cos((r + noisePhaseB) * 0.4)) * 2.0;
                rawVal += (dist * 0.5);

                let tier = Math.round(rawVal);
                tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));

                if (dist < 1.5) tier = 0;

                tiers.set(k, tier);
            }
        }

        const smoothedTiers = new Map<string, number>();
        tiers.forEach((tier, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let minN = tier;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tiers.has(nk)) minN = Math.min(minN, tiers.get(nk)! + 1);
            });
            smoothedTiers.set(key, minN);
        });

        smoothedTiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine, W, H);
        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine, W: number, H: number) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        const centerCol = Math.floor(W / 2);
        const centerRow = Math.floor(H / 2);
        const centerHex = HexUtils.offsetToAxial(centerCol, centerRow, engine.mapConfig);

        const keys = Array.from(system.getMapKeys());

        keys.forEach((key) => {
            const [q, r] = key.split(',').map(Number);
            const dist = HexUtils.dist({q, r}, centerHex);

            if (dist < 2.5) return; 
            if (engine.getAgentAt(q, r)) return;

            const noise = Math.sin(q * 0.8) * Math.cos(r * 0.8);
            if (noise > 0.4 && Math.random() < 0.3) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }
}

import { BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

// 幾何常數
const PEDESTAL_DEPTH = 300; 
const EXPANSION_BIAS = 0.6; 

export const TerrainRenderer = {
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        const drawX = Math.floor(x);
        const drawY = Math.floor(y);

        const visualTopY = -Math.floor(height);

        const r = size + EXPANSION_BIAS;
        const vertices = HexGeometry.getVertices(r, true, layout); 

        ctx.save();
        ctx.translate(drawX, drawY);

        const drawFace = (idx1: number, idx2: number, color: string) => {
            const v1 = vertices[idx1];
            const v2 = vertices[idx2];

            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v2.x, v2.y + visualTopY);
            ctx.lineTo(v2.x, v2.y + PEDESTAL_DEPTH);
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH);
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = 'rgba(255,255,255,0.05)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v1.x, v1.y + visualTopY + BLOCK_HEIGHT * 2);
            ctx.stroke();
        };

        if (layout === 'FLAT') {
            drawFace(1, 0, theme.sideDark);
            drawFace(2, 1, theme.sideLight);
            drawFace(3, 2, theme.sideDark);
        } else {
            drawFace(1, 0, theme.sideDark);
            drawFace(2, 1, theme.sideLight);
        }

        ctx.translate(0, visualTopY);

        if (Number.isFinite(r) && r > 0) {
            const topGrad = ctx.createLinearGradient(-r, -r, r, r);
            topGrad.addColorStop(0, theme.rim); 
            topGrad.addColorStop(0.5, theme.top);
            topGrad.addColorStop(1, theme.sideDark); 
            ctx.fillStyle = topGrad;
        } else {
            ctx.fillStyle = theme.top;
        }

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.0;
        ctx.globalAlpha = 0.5;
        ctx.stroke();

        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        }

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = Math.floor(baseY) - Math.floor(height);
        if (type === 'FOREST' || type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { Hex, Point, Cube, HexLayout } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

export { Cube };

const SQRT3 = Math.sqrt(3);

const DIRECTIONS = [
    { q: 1, r: 0 }, { q: 1, r: -1 }, { q: 0, r: -1 },
    { q: -1, r: 0 }, { q: -1, r: 1 }, { q: 0, r: 1 }
];

export const HexMath = {

    directions: DIRECTIONS,

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    hexToPixel(q: number, r: number, offsetX: number, offsetY: number, layout: HexLayout): Point {
        let x = 0;
        let y = 0;

        if (layout === 'FLAT') {
            x = HEX_SIZE * (1.5 * q);
            y = HEX_SIZE * (SQRT3/2 * q + SQRT3 * r);
        } else {
            x = HEX_SIZE * (SQRT3 * q + SQRT3/2 * r);
            y = HEX_SIZE * (1.5 * r);
        }

        y = y * ISO_SCALE_Y;

        return {
            x: x + offsetX,
            y: y + offsetY
        };
    },

    pixelToHex(x: number, y: number, offsetX: number, offsetY: number, layout: HexLayout): Hex {
        const dx = x - offsetX;
        const dy = (y - offsetY) / ISO_SCALE_Y;

        let q = 0;
        let r = 0;

        if (layout === 'FLAT') {
            q = (2/3 * dx) / HEX_SIZE;
            r = (-1/3 * dx + SQRT3/3 * dy) / HEX_SIZE;
        } else {
            q = (SQRT3/3 * dx - 1/3 * dy) / HEX_SIZE;
            r = (2/3 * dy) / HEX_SIZE;
        }

        return this.cubeToAxial(this.cubeRound(this.axialToCube({q, r})));
    },

    distance(a: Hex, b: Hex): number {
        const ac = this.axialToCube(a);
        const bc = this.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = this.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(this.cubeToAxial(this.cubeRound(cubeLerp)));
        }
        return results;
    },

    neighbors(h: Hex): Hex[] {
        return DIRECTIONS.map(d => ({ q: h.q + d.q, r: h.r + d.r }));
    }
};

import { HEX_SIZE, ISO_SCALE_Y } from "../constants";
import { Hex, Point, HexLayout } from "../types";
import { HexMath } from "./math/HexMath"; // Strict relative path

export interface MapConfig {
    w: number;
    h: number;
    offsetX: number;
    offsetY: number;
    layout: HexLayout;
}
const Q_BIT_SHIFT = 16;
const Q_OFFSET = 128;
const R_OFFSET = 128;
export const NEIGHBOR_HASH_OFFSETS = [
    (1 << Q_BIT_SHIFT),
    (1 << Q_BIT_SHIFT) - 1,
    -1,
    -(1 << Q_BIT_SHIFT),
    -(1 << Q_BIT_SHIFT) + 1,
    1
];
export function getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
    if (phase === 'IDLE') return 0;
    const cx = mapConfig.offsetX;
    const cy = mapConfig.offsetY;
    const dist = Math.sqrt((x - cx)**2 + (y - cy)**2);
    const maxDist = 1000;
    const d = Math.min(1, dist / maxDist);
    const BASE_OFFSET = 1500;
    if (phase === 'OUT') {
        const startT = d * 0.3;
        if (t < startT) return 0;
        let localT = (t - startT) * 1.8;
        localT = Math.max(0, Math.min(1, localT));
        const s = 0.5;
        const eased = localT * localT * ((s + 1) * localT - s);
        return eased * BASE_OFFSET;
    } else if (phase === 'IN') {
        const startT = d * 0.2;
        if (t < startT) return BASE_OFFSET;
        let localT = (t - startT) * 1.5;
        localT = Math.max(0, Math.min(1, localT));
        const eased = 1 - Math.pow(1 - localT, 4);
        return (1 - eased) * BASE_OFFSET;
    }
    return 0;
}
export const HexUtils = {
    offsetToAxial: (col: number, row: number, config: MapConfig): Hex => {
        if (config.layout === 'FLAT') {
            const q = col;
            const r = row - (col - (col & 1)) / 2;
            return { q, r };
        } else {
            const q = col - (row - (row & 1)) / 2;
            const r = row;
            return { q, r };
        }
    },
    toPx: (q: number, r: number, config: MapConfig): Point => {
        return HexMath.hexToPixel(q, r, config.offsetX, config.offsetY, config.layout);
    },
    fromPx: (x: number, y: number, config: MapConfig): Hex => {
        const frac = HexMath.pixelToHex(x, y, config.offsetX, config.offsetY, config.layout);
        return HexMath.cubeToAxial(HexMath.cubeRound(HexMath.axialToCube(frac)));
    },
    round: (q: number, r: number): Hex => {
        const c = HexMath.cubeRound({x: q, z: r, y: -q-r});
        return { q: c.x, r: c.z };
    },
    dist: (a: Hex, b: Hex): number => {
        return HexMath.distance(a, b);
    },
    lerp: (a: number, b: number, t: number): number => a + (b - a) * t,
    key: (h: Hex): string => `${Math.round(h.q)},${Math.round(h.r)}`,
    hash: (q: number, r: number): number => {
        return (Math.round(q) + Q_OFFSET) << Q_BIT_SHIFT | (Math.round(r) + R_OFFSET);
    },
    unhash: (h: number): Hex => {
        const r = (h & 0xFFFF) - R_OFFSET;
        const q = (h >> Q_BIT_SHIFT) - Q_OFFSET;
        return { q, r };
    },
    neighbors: (h: Hex): Hex[] => {
        return HexMath.neighbors(h);
    },
    range: (center: Hex, n: number): Hex[] => {
        return HexMath.range(center, n);
    },
    line: (a: Hex, b: Hex): Hex[] => {
        return HexMath.line(a, b);
    }
};
export const Vector = {
    sub: (a: Point, b: Point): Point => ({ x: a.x - b.x, y: a.y - b.y }),
    add: (a: Point, b: Point): Point => ({ x: a.x + b.x, y: a.y + b.y }),
    mult: (a: Point, s: number): Point => ({ x: a.x * s, y: a.y * s }),
    lerp: (a: Point, b: Point, t: number): Point => ({
        x: a.x + (b.x - a.x) * t,
        y: a.y + (b.y - a.y) * t
    }),
    mag: (a: Point): number => Math.sqrt(a.x * a.x + a.y * a.y),
    normalize: (a: Point): Point => {
        const m = Vector.mag(a);
        return m === 0 ? { x: 0, y: 0 } : { x: a.x / m, y: a.y / m };
    },
    dist: (a: Point, b: Point): number => Vector.mag(Vector.sub(a, b))
};

import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
// [FIX] 改用正確的數學庫，移除 HexUtils
import { HexMath } from "./HexMath"; 
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {

    /**
     * SSOT: 計算單位視覺中心點 Y 座標
     * 考慮地形高度、物理跳躍高度(z)、模型偏移
     */
    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    /**
     * 獲取單位的「核心錨點」(通常是胸口)
     * 用於投射物命中、雷射連接
     */
    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);

        // 胸口高度計算：基礎偏移 + 物理高度 + 模型高度的 40%
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;

        return { x: agent.px, y: agent.py, z: z };
    }

    /**
     * 獲取單位的「腳底錨點」
     * 用於地面法陣、影子、傳送門
     */
    public static getUnitFeet(agent: Agent, engine: GameEngine): Point3D {
        const terrainH = engine.map.getTerrainHeight(agent.q, agent.r);
        return { x: agent.px, y: agent.py, z: terrainH + agent.physics.z + 2 }; // +2 解決穿插
    }

    public static getHexCenter(q: number, r: number, engine: GameEngine): Point3D {
        // [FIX] 這裡改用 HexMath.hexToPixel
        // 注意：我們不需要傳入 engine.mapConfig 的 offset，因為渲染器通常以 (0,0) 為中心繪製
        // 若您的系統確實依賴全域 offset，請改為：
        // const raw = HexMath.hexToPixel(q, r, engine.mapConfig.layout);
        // return { x: raw.x + engine.mapConfig.offsetX, ... }

        const p = HexMath.hexToPixel(
            q, 
            r, 
            engine.mapConfig.offsetX, 
            engine.mapConfig.offsetY, 
            engine.mapConfig.layout
        );
        const h = engine.map.getTerrainHeight(q, r);

        return { x: p.x, y: p.y, z: h + 2 }; 
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };

        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) {
            return this.getUnitAnchor(agent, engine);
        }

        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                return this.getHexCenter(q, r, engine);
            }
        }

        return { x: 0, y: 0, z: -9999 };
    }
}

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

export class MapGenerator {
    public static randomize(system: MapSystem, engine: GameEngine) {
        const layout = engine.mapConfig.layout;
        let cols, rows;

        if (layout === 'FLAT') {
            cols = 8 + Math.floor(Math.random() * 2); 
            rows = 10 + Math.floor(Math.random() * 2); 
        } else {
            cols = 7 + Math.floor(Math.random() * 2); 
            rows = 12 + Math.floor(Math.random() * 2); 
        }

        engine.mapConfig.w = cols; 
        engine.mapConfig.h = rows; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();
        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        const centerQ = Math.floor((W - 1) / 2);
        const centerR = Math.floor((H - 1) / 2);
        const centerHex = { q: centerQ, r: centerR };

        // 用於計算前景深度的參考值
        const centerSum = centerQ + centerR;

        const noisePhaseA = Math.random() * 1000;
        const noisePhaseB = Math.random() * 1000;

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const k = HexUtils.key({q, r});
                system.registerTile(q, r);

                const dist = HexUtils.dist({q, r}, centerHex);

                // 核心數學：階梯狀高度函數 (Stepped Height Field)
                let rawVal = (Math.sin((q + noisePhaseA) * 0.4) + Math.cos((r + noisePhaseB) * 0.4)) * 2.0;
                rawVal += (dist * 0.5); // 基礎碗狀趨勢

                // 視覺修正：前景壓低 (防止遮擋戰場視線)
                // 根據 Diamond Grid 投影邏輯，(q+r) 越大表示越靠近螢幕下方 (前景)
                // 我們對前景區域施加高度懲罰，形成類似羅馬競技場的單向開口結構
                const visualDepth = (q + r) - centerSum;
                if (visualDepth > 0) {
                    rawVal -= (visualDepth * 0.8); 
                }

                // 離散化為 Tier 層級
                let tier = Math.round(rawVal);
                tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));

                // 確保中心區域平坦
                if (dist < 1.5) tier = 0;

                tiers.set(k, tier);
            }
        }

        // 高度場平滑
        const smoothedTiers = new Map<string, number>();
        tiers.forEach((tier, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let minN = tier;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tiers.has(nk)) minN = Math.min(minN, tiers.get(nk)! + 1);
            });
            smoothedTiers.set(key, minN);
        });

        smoothedTiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine, W, H);
        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine, W: number, H: number) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        const centerHex = { q: Math.floor(W/2), r: Math.floor(H/2) };
        const keys = Array.from(system.getMapKeys());

        keys.forEach((key) => {
            const [q, r] = key.split(',').map(Number);
            const dist = HexUtils.dist({q, r}, centerHex);

            if (dist < 2.5) return; 
            if (engine.getAgentAt(q, r)) return;

            const noise = Math.sin(q * 0.8) * Math.cos(r * 0.8);
            if (noise > 0.4 && Math.random() < 0.3) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }
}

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

export class MapGenerator {
    public static randomize(system: MapSystem, engine: GameEngine) {
        const layout = engine.mapConfig.layout;
        let cols, rows;

        if (layout === 'FLAT') {
            cols = 8 + Math.floor(Math.random() * 2); 
            rows = 10 + Math.floor(Math.random() * 2); 
        } else {
            cols = 7 + Math.floor(Math.random() * 2); 
            rows = 12 + Math.floor(Math.random() * 2); 
        }

        engine.mapConfig.w = cols; 
        engine.mapConfig.h = rows; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();
        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        const centerQ = Math.floor((W - 1) / 2);
        const centerR = Math.floor((H - 1) / 2);
        const centerHex = { q: centerQ, r: centerR };

        // 用於計算前景深度的參考值
        const centerSum = centerQ + centerR;

        const noisePhaseA = Math.random() * 1000;
        const noisePhaseB = Math.random() * 1000;

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const k = HexUtils.key({q, r});
                system.registerTile(q, r);

                const dist = HexUtils.dist({q, r}, centerHex);

                // 核心數學：階梯狀高度函數 (Stepped Height Field)
                let rawVal = (Math.sin((q + noisePhaseA) * 0.4) + Math.cos((r + noisePhaseB) * 0.4)) * 2.0;
                rawVal += (dist * 0.5); // 基礎碗狀趨勢

                // 視覺修正：前景壓低 (防止遮擋戰場視線)
                // 根據 Diamond Grid 投影邏輯，(q+r) 越大表示越靠近螢幕下方 (前景)
                // 我們對前景區域施加高度懲罰，形成類似羅馬競技場的單向開口結構
                const visualDepth = (q + r) - centerSum;
                if (visualDepth > 0) {
                    // [UPDATED] 加強懲罰係數，確保前景不會生成高地 (從 0.8 提升至 1.5)
                    rawVal -= (visualDepth * 1.5); 
                    // 額外抑制遠端距離加成，避免邊角過高
                    if (dist > 2) rawVal -= (dist * 0.2);
                }

                // 離散化為 Tier 層級
                let tier = Math.round(rawVal);
                tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));

                // 確保中心區域平坦
                if (dist < 1.5) tier = 0;

                tiers.set(k, tier);
            }
        }

        // 高度場平滑
        const smoothedTiers = new Map<string, number>();
        tiers.forEach((tier, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let minN = tier;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tiers.has(nk)) minN = Math.min(minN, tiers.get(nk)! + 1);
            });
            smoothedTiers.set(key, minN);
        });

        smoothedTiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine, W, H);
        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine, W: number, H: number) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        const centerHex = { q: Math.floor(W/2), r: Math.floor(H/2) };
        const keys = Array.from(system.getMapKeys());

        keys.forEach((key) => {
            const [q, r] = key.split(',').map(Number);
            const dist = HexUtils.dist({q, r}, centerHex);

            if (dist < 2.5) return; 
            if (engine.getAgentAt(q, r)) return;

            const noise = Math.sin(q * 0.8) * Math.cos(r * 0.8);
            if (noise > 0.4 && Math.random() < 0.3) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }
}
